"""
Proje kokunde calistir:  python guncelle.py
Su dosyalari son surumle yazar (var olanlari .bak olarak saklar):
  algorithms/model.py, algorithms/reinforcementagent.py,
  simulation_core/engine.py, simulation_core/slow_zones.py,
  simulation_app/ui/main_window.py, train_headless.py
"""
import os, shutil

FILES = {
    'algorithms/model.py': '"""\nDroneDQNAlgorithm: motor ile paylasilan ajan arasindaki kopru.\n\nKarar zamanlamasi olay tabanlidir. Karar turu su durumlarda acilir:\nbolum basi, hedef ziyareti, motorun rolleri kendisinin degistirmesi\n(ekip dagilmasi vb.), en zayif halkanin %90 esigini yukari yonde gecmesi\nve MAX_DECISION_INTERVAL dolmasi. Turda tum drone\'lar sirayla karar verir.\nAyni turda once karar verenin secimi sonrakinin gozleminde gorunur.\n\nMotor (engine.py) ile dogrulanan davranis:\n- _apply_plan sirasi: free_uav_ids -> goal -> relay -> slave. Her atama\n  once _free_uav cagirir (ekibini dagitir, hedefini birakir).\n- Relay de liderin my_slave_list\'ine eklenir; lider serbest kalinca dagilir.\n- Ayni lidere yeniden RelayAssignment yalnizca target_position\'i yeniler\n  (_free_uav + yeniden ekleme). Relay\'in kendi takipcisi varsa onlar\n  dagilacagi icin o Relay guncellenmez.\n"""\n\nfrom __future__ import annotations\n\nimport os\nimport random\nfrom collections import deque\nfrom typing import Dict, List, Optional, Tuple\n\nimport numpy as np\n\nfrom simulation_core.algorithm_api import (\n    AlgorithmPlan,\n    GoalAssignment,\n    Position,\n    RelayAssignment,\n    SimulationAlgorithm,\n    SimulationContext,\n    SlaveAssignment,\n)\nfrom simulation_core.topology import (\n    build_distance_matrix,\n    find_connected_components,\n)\nfrom algorithms.reinforcementagent import (\n    EPSILON_DECAY_DECISIONS,\n    GAMMA,\n    MARGIN_ALARM_RATIO,\n    MAX_DECISION_INTERVAL,\n    MAX_EPISODE_STEPS,\n    SharedAgent,\n    Transition,\n    WorldView,\n    bottleneck_edge,\n    compute_relay_point,\n    normalize_role,\n    pairwise_distances,\n    step_reward,\n)\n\n\nCHECKPOINT_DIR = "./model"\nCHECKPOINT_LAST = os.path.join(CHECKPOINT_DIR, "drone_dqn_shared_last.pth")\nCHECKPOINT_BEST = os.path.join(CHECKPOINT_DIR, "drone_dqn_shared_best.pth")\nZONES_CHECKPOINT_LAST = os.path.join(CHECKPOINT_DIR, "drone_dqn_zones_last.pth")\nZONES_CHECKPOINT_BEST = os.path.join(CHECKPOINT_DIR, "drone_dqn_zones_best.pth")\nSAVE_EVERY_EPISODES = 10\nAVG_WINDOW = 50\n\nDYNAMIC_RELAY = True\nRELAY_UPDATE_MIN_SHIFT = 10.0\n\nRoleKey = Tuple[str, Optional[int], Optional[int]]\n\n\ndef _role_key(uav) -> RoleKey:\n    role = normalize_role(uav.state)\n    return (\n        role,\n        uav.target_goal_id if role == "Leader" else None,\n        uav.leader_id if role in ("Slave", "Relay") else None,\n    )\n\n\nclass DroneDQNAlgorithm(SimulationAlgorithm):\n    name = "drone_dqn"\n    display_name = "Drone DQN"\n    description = "Paylasilan agli, egosentrik gozlemli, olay tabanli DQN."\n\n    checkpoint_last: str = CHECKPOINT_LAST\n    checkpoint_best: str = CHECKPOINT_BEST\n    # Kendi kaydi yoksa egitimin baslatilacagi baska modelin kayitlari (transfer).\n    warm_start_paths: Tuple[str, ...] = ()\n\n    def __init__(\n        self,\n        max_episode_steps: Optional[int] = MAX_EPISODE_STEPS,\n        seed: Optional[int] = None,\n        verbose: bool = True,\n        auto_save: bool = True,\n    ) -> None:\n        self.training_enabled: bool = False\n        self.verbose = verbose\n        self.auto_save = auto_save\n        self.last_episode: Optional[dict] = None\n        self.max_episode_steps = max_episode_steps\n        self.seed = seed\n        self.agent: Optional[SharedAgent] = None\n        self._rng = random.Random(seed)\n        self._episode_counter = 0\n        self._returns: deque = deque(maxlen=AVG_WINDOW)\n        self._disconnects: deque = deque(maxlen=AVG_WINDOW)\n        self._reset_episode()\n\n    # ------------------------------------------------------------------ #\n    # Disa acik arayuz                                                   #\n    # ------------------------------------------------------------------ #\n\n    def enable_training(self, enabled: bool) -> None:\n        self.training_enabled = bool(enabled)\n\n    def reset(self) -> None:\n        self._reset_episode()\n\n    def _reset_episode(self) -> None:\n        self.episode_steps = 0\n        self.episode_reward = 0.0\n        self._pending: Dict[int, Tuple[np.ndarray, np.ndarray, int]] = {}\n        self._acc_reward = 0.0\n        self._acc_discount = 1.0\n        self._force_decision = True\n        self._event = False\n        self._steps_since_decision = 0\n        self._motions: Dict[int, Tuple[float, float]] = {}\n        self._role_since: Dict[int, int] = {}\n        self._last_roles: Dict[int, RoleKey] = {}\n        self._prev_visited = 0\n        self._prev_ratio = 0.0\n        self._decision_rounds = 0\n        self._role_changes = 0\n\n    def _ensure_agent(self) -> None:\n        if self.agent is not None:\n            return\n        self.agent = SharedAgent(seed=self.seed)\n        path = self.load_into(self.agent, self.training_enabled)\n        if path is None:\n            print(f"[{self.display_name}] Yeni ag ile baslaniyor.")\n        else:\n            print(f"[{self.display_name}] Yuklendi: {path}")\n\n    @classmethod\n    def load_into(cls, agent: SharedAgent, training: bool) -> Optional[str]:\n        """Bu modelin kaydini yukler. Egitimde kendi kaydi yoksa warm_start_paths\n        denenir; bu durumda kesif yeniden acilir ve en iyi skor sifirlanir."""\n        own = [cls.checkpoint_last] if training else [cls.checkpoint_best, cls.checkpoint_last]\n        for path in own:\n            if not os.path.exists(path):\n                continue\n            try:\n                agent.load(path)\n                return path\n            except ValueError as exc:\n                print(f"[{cls.display_name}] Yuklenemedi ({path}): {exc}")\n        if not training:\n            return None\n        for path in cls.warm_start_paths:\n            if not os.path.exists(path):\n                continue\n            try:\n                agent.load(path)\n            except ValueError as exc:\n                print(f"[{cls.display_name}] Baslangic modeli yuklenemedi ({path}): {exc}")\n                continue\n            agent.decisions = min(agent.decisions, EPSILON_DECAY_DECISIONS // 2)\n            agent.episodes = 0\n            agent.best_avg = float("-inf")\n            return f"{path} (baslangic modeli)"\n        return None\n\n    # ------------------------------------------------------------------ #\n    # Plan                                                               #\n    # ------------------------------------------------------------------ #\n\n    def build_plan(self, context: SimulationContext) -> AlgorithmPlan:\n        if not context.uavs or not context.goals:\n            return AlgorithmPlan.empty()\n\n        visited_now = sum(1 for g in context.goals if g.state == "Visited")\n        single_visit = (\n            getattr(context.config, "target_eval_mode", "single_visit")\n            == "single_visit"\n        )\n        if single_visit and visited_now < self._prev_visited:\n            # GUI reset() cagirmadan yeni senaryo baslatmis.\n            self._reset_episode()\n\n        if all(g.state == "Visited" for g in context.goals):\n            return AlgorithmPlan.empty()\n\n        self._ensure_agent()\n\n        relay_updates = (\n            self._dynamic_relay_updates(context) if DYNAMIC_RELAY else []\n        )\n\n        due = (\n            self._force_decision\n            or self._event\n            or self._steps_since_decision >= MAX_DECISION_INTERVAL\n        )\n        if not due:\n            if relay_updates:\n                return AlgorithmPlan(relay_assignments=tuple(relay_updates))\n            return AlgorithmPlan.empty()\n\n        return self._decision_round(context, relay_updates)\n\n    def _decision_round(\n        self, context: SimulationContext, relay_updates: List[RelayAssignment]\n    ) -> AlgorithmPlan:\n        world = WorldView(\n            context,\n            self._motions,\n            self._role_since,\n            self.episode_steps,\n            self.max_episode_steps,\n        )\n        order = list(world.uav_ids)\n        if self.training_enabled:\n            self._rng.shuffle(order)\n\n        # (tur, referans, relay noktasi). Relay noktasi atama aninda saklanir:\n        # ayni turda lideri sonradan degisirse takipci sanal olarak dagilir,\n        # ama motor da atamayi isleyip ayni sekilde dagitacagi icin plana yazilir.\n        decided: Dict[int, Tuple[str, Optional[int], Optional[np.ndarray]]] = {}\n\n        for uid in order:\n            obs = world.observation(uid)\n            cands = world.candidates(uid)\n            feats = np.stack([world.candidate_features(uid, c) for c in cands])\n\n            if self.training_enabled and uid in self._pending:\n                p_obs, p_feats, p_action = self._pending.pop(uid)\n                self.agent.push(\n                    Transition(\n                        obs=p_obs,\n                        cand_feats=p_feats,\n                        action=p_action,\n                        reward=self._acc_reward,\n                        discount=self._acc_discount,\n                        done=False,\n                        next_obs=obs,\n                        next_cand_feats=feats,\n                    )\n                )\n\n            keep_index = 0 if cands[0][0] == "keep" else None\n            action = self.agent.select_action(\n                obs, feats, self.training_enabled, keep_index\n            )\n            cand = cands[action]\n\n            if self.training_enabled:\n                self._pending[uid] = (obs, feats, action)\n\n            if world.apply(uid, cand):\n                point = world.relay_point[uid]\n                decided[uid] = (\n                    cand[0], cand[1], None if point is None else point.copy()\n                )\n                self._role_changes += 1\n                self._role_since[uid] = self.episode_steps\n\n        goal_as: List[GoalAssignment] = []\n        slave_as: List[SlaveAssignment] = []\n        relay_as: List[RelayAssignment] = []\n        free_ids: List[int] = []\n\n        for uid, (kind, ref, point) in decided.items():\n            if kind == "free":\n                free_ids.append(uid)\n            elif kind == "leader":\n                goal_as.append(GoalAssignment(uav_id=uid, goal_id=ref, role="Leader"))\n            elif kind == "slave":\n                slave_as.append(SlaveAssignment(uav_id=uid, leader_id=ref))\n            elif kind == "relay":\n                relay_as.append(\n                    RelayAssignment(\n                        uav_id=uid,\n                        leader_id=ref,\n                        target_position=Position(float(point[0]), float(point[1])),\n                    )\n                )\n\n        # Dinamik relay guncellemesi de _free_uav cagirir. Bu turda bu Relay\'e\n        # yeni takipci atandiysa ya da lideri degistiyse guncelleme atlanir.\n        new_leaders = {\n            ref for (kind, ref, _) in decided.values() if kind in ("slave", "relay")\n        }\n        for upd in relay_updates:\n            if (\n                upd.uav_id not in decided\n                and upd.leader_id not in decided\n                and upd.uav_id not in new_leaders\n            ):\n                relay_as.append(upd)\n\n        # Beklenen roller; motor farkli uygularsa finish_step olay olarak yakalar.\n        for uid in world.uav_ids:\n            self._last_roles[uid] = (\n                world.role[uid], world.target[uid], world.leader[uid]\n            )\n\n        self._acc_reward = 0.0\n        self._acc_discount = 1.0\n        self._force_decision = False\n        self._event = False\n        self._steps_since_decision = 0\n        self._decision_rounds += 1\n\n        if not (goal_as or slave_as or relay_as or free_ids):\n            return AlgorithmPlan.empty()\n        return AlgorithmPlan(\n            goal_assignments=tuple(goal_as),\n            relay_assignments=tuple(relay_as),\n            slave_assignments=tuple(slave_as),\n            free_uav_ids=tuple(free_ids),\n        )\n\n    def _dynamic_relay_updates(\n        self, context: SimulationContext\n    ) -> List[RelayAssignment]:\n        uavs = list(context.uavs)\n        index = {u.id: i for i, u in enumerate(uavs)}\n        pts = [[u.position.x, u.position.y] for u in uavs]\n        if context.ground is not None:\n            pts.append([context.ground.position.x, context.ground.position.y])\n        node_pos = np.array(pts, dtype=np.float64).reshape(-1, 2)\n\n        out: List[RelayAssignment] = []\n        for u in uavs:\n            if u.state != "Relay" or u.leader_id not in index:\n                continue\n            if any(\n                o.state in ("Slave", "Relay") and o.leader_id == u.id for o in uavs\n            ):\n                continue\n            leader_id = u.leader_id\n            exclude = {index[u.id]} | {\n                index[o.id]\n                for o in uavs\n                if o.state in ("Slave", "Relay") and o.leader_id == leader_id\n            }\n            point = compute_relay_point(node_pos, index[leader_id], exclude)\n            if u.relay_target is not None:\n                shift = float(\n                    np.hypot(point[0] - u.relay_target.x, point[1] - u.relay_target.y)\n                )\n                if shift < RELAY_UPDATE_MIN_SHIFT:\n                    continue\n            out.append(\n                RelayAssignment(\n                    uav_id=u.id,\n                    leader_id=leader_id,\n                    target_position=Position(float(point[0]), float(point[1])),\n                )\n            )\n        return out\n\n    # ------------------------------------------------------------------ #\n    # Adim sonu                                                          #\n    # ------------------------------------------------------------------ #\n\n    def finish_step(\n        self, context: SimulationContext, next_context: SimulationContext\n    ) -> Optional[str]:\n        self.episode_steps += 1\n        self._steps_since_decision += 1\n\n        for u in next_context.uavs:\n            prev = context.uav_by_id(u.id)\n            if prev is None:\n                self._motions[u.id] = (0.0, 0.0)\n            else:\n                self._motions[u.id] = (\n                    u.position.x - prev.position.x,\n                    u.position.y - prev.position.y,\n                )\n\n        visited_now = sum(1 for g in next_context.goals if g.state == "Visited")\n        new_visits = max(0, visited_now - self._prev_visited)\n        self._prev_visited = visited_now\n        remaining = len(next_context.goals) - visited_now\n\n        positions = [u.position for u in next_context.uavs]\n        if next_context.ground is not None:\n            positions.append(next_context.ground.position)\n        components = find_connected_components(\n            build_distance_matrix(positions),\n            next_context.comm_thr,\n            threshold_ratio=1.0,\n        )\n        disconnected = len(components) > 1\n        all_visited = remaining == 0\n\n        node_pos = np.array([[p.x, p.y] for p in positions], dtype=np.float64)\n        thr = next_context.comm_thr if next_context.comm_thr > 0 else 1.0\n        ratio = bottleneck_edge(pairwise_distances(node_pos))[0] / thr\n\n        reward = step_reward(new_visits, remaining, disconnected, all_visited, ratio)\n        self.episode_reward += reward\n        self._acc_reward += self._acc_discount * reward\n        self._acc_discount *= GAMMA\n\n        if new_visits > 0:\n            self._event = True\n        if ratio > MARGIN_ALARM_RATIO >= self._prev_ratio:\n            self._event = True\n        self._prev_ratio = ratio\n\n        for u in next_context.uavs:\n            key = _role_key(u)\n            old = self._last_roles.get(u.id)\n            if old is not None and old != key:\n                self._event = True\n                self._role_since[u.id] = self.episode_steps\n            self._last_roles[u.id] = key\n\n        stop: Optional[str] = None\n        terminal = False\n        if disconnected:\n            stop, terminal = "network_disconnected", True\n        elif all_visited:\n            stop, terminal = "all_goals_visited", True\n        elif (\n            self.max_episode_steps is not None\n            and self.episode_steps >= self.max_episode_steps\n        ):\n            # GUI yalnizca bu ucunu taniyor; "time_limit" dongusu kilitler.\n            stop, terminal = "time_elapsed", False\n\n        if stop is not None:\n            self._end_episode(next_context, stop, terminal, visited_now)\n        return stop\n\n    def _end_episode(\n        self,\n        next_context: SimulationContext,\n        stop: str,\n        terminal: bool,\n        visited_now: int,\n    ) -> None:\n        agent = self.agent\n        if self.training_enabled and agent is not None and self._pending:\n            if terminal:\n                for p_obs, p_feats, p_action in self._pending.values():\n                    agent.push(\n                        Transition(\n                            obs=p_obs,\n                            cand_feats=p_feats,\n                            action=p_action,\n                            reward=self._acc_reward,\n                            discount=self._acc_discount,\n                            done=True,\n                            next_obs=None,\n                            next_cand_feats=None,\n                        )\n                    )\n            else:\n                # Truncation: terminal degil, sonraki durumdan bootstrap yapilir.\n                world = WorldView(\n                    next_context,\n                    self._motions,\n                    self._role_since,\n                    self.episode_steps,\n                    self.max_episode_steps,\n                )\n                for uid, (p_obs, p_feats, p_action) in self._pending.items():\n                    if uid not in world.index:\n                        continue\n                    cands = world.candidates(uid)\n                    feats = np.stack(\n                        [world.candidate_features(uid, c) for c in cands]\n                    )\n                    agent.push(\n                        Transition(\n                            obs=p_obs,\n                            cand_feats=p_feats,\n                            action=p_action,\n                            reward=self._acc_reward,\n                            discount=self._acc_discount,\n                            done=False,\n                            next_obs=world.observation(uid),\n                            next_cand_feats=feats,\n                        )\n                    )\n\n        self._episode_counter += 1\n        self._returns.append(self.episode_reward)\n        self._disconnects.append(stop == "network_disconnected")\n        avg = float(np.mean(self._returns))\n        disconnect_rate = float(np.mean(self._disconnects))\n\n        self.last_episode = {\n            "reward": self.episode_reward,\n            "visited": visited_now,\n            "goals": len(next_context.goals),\n            "steps": self.episode_steps,\n            "end": stop,\n            "role_changes": self._role_changes,\n            "rounds": self._decision_rounds,\n        }\n\n        if self.training_enabled and agent is not None:\n            agent.episodes += 1\n            if self.auto_save:\n                if len(self._returns) >= AVG_WINDOW and avg > agent.best_avg:\n                    agent.best_avg = avg\n                    self._safe_save(self.checkpoint_best)\n                if agent.episodes % SAVE_EVERY_EPISODES == 0:\n                    self._safe_save(self.checkpoint_last)\n\n        if agent is not None and self.verbose:\n            loss = f"{agent.last_loss:.4f}" if agent.last_loss is not None else "n/a"\n            best = f"{agent.best_avg:.2f}" if agent.best_avg > float("-inf") else "n/a"\n            print(\n                f"Episode {self._episode_counter} | "\n                f"Reward {self.episode_reward:.2f} | Avg {avg:.2f} | BestAvg {best} | "\n                f"Visited {visited_now}/{len(next_context.goals)} | "\n                f"RoleChanges {self._role_changes} | Rounds {self._decision_rounds} | "\n                f"DisconnectRate {disconnect_rate:.2f} | Steps {self.episode_steps} | "\n                f"End {stop} | Epsilon {agent.epsilon if self.training_enabled else 0.0:.3f} | "\n                f"Loss {loss} | Updates {agent.updates} | Replay {len(agent.memory)}"\n            )\n\n        self._reset_episode()\n\n    def _safe_save(self, path: str) -> None:\n        try:\n            self.agent.save(path)\n        except Exception as exc:\n            print(f"[DroneDQN] Kayit basarisiz ({path}): {exc}")\n\n\nclass DroneDQNSlowZoneAlgorithm(DroneDQNAlgorithm):\n    """Yavaslatma bolgeli ortam icin ayni ajan, ayri kayit.\n\n    Gozlem ve ag aynidir: bolgeler ajana verilmez, ajan yalnizca kendi\n    gerceklesen hareketinden (gozlemdeki hareket vektoru / nominal hiz)\n    yavasladigini hissedebilir. Ilk egitimde normal modelden baslar.\n    """\n\n    name = "drone_dqn_zones"\n    display_name = "Drone DQN (Yavaslatma Bolgeli)"\n    description = "Yavaslatma bolgelerini bilmeden, yalnizca hissederek ogrenen DQN."\n\n    checkpoint_last = ZONES_CHECKPOINT_LAST\n    checkpoint_best = ZONES_CHECKPOINT_BEST\n    warm_start_paths = (CHECKPOINT_BEST, CHECKPOINT_LAST)\n\n\nALGORITHMS = [DroneDQNAlgorithm, DroneDQNSlowZoneAlgorithm]\n',
    'algorithms/reinforcementagent.py': '"""\nPaylasilan (parameter sharing) DQN ajani.\n\n- Tek ag, tum drone\'lar kullanir. Gozlem egosentriktir (ben-merkezli).\n- Ag her aday secenek (keep, free, leader+hedef, slave+drone, relay+drone)\n  icin ayri bir Q uretir. Bu yuzden N ve M degisse de ayni ag calisir.\n- Double DQN + Polyak target, Huber loss, AdamW, LayerNorm, ReLU.\n- SMDP: hedef = R_birikimli + gamma^k * Q_target(sonraki karar noktasi).\n- Davranis kurali yok. Yalnizca yapisal gecerlilik maskesi var:\n  Visited/baskasina atanmis hedefe atama yok, kendine lider olma yok,\n  takip dongusu (A->B->A) yok.\n"""\n\nfrom __future__ import annotations\n\nimport copy\nimport os\nimport random\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Sequence, Set, Tuple\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\n# ====================================================================== #\n# Sabitler                                                               #\n# ====================================================================== #\n\nOBSERVATION_VERSION = 8\nTRAINING_CONFIG_VERSION = 8\n\n# Replay ve egitim\nMAX_MEMORY = 100_000\nBATCH_SIZE = 64\nMIN_REPLAY_SIZE = 1_000\nTRAIN_EVERY_TRANSITIONS = 4\nLR = 3e-4\nWEIGHT_DECAY = 1e-4\nGAMMA = 0.995  # ortam adimi basina; karar arasi indirim gamma^k\nHIDDEN_SIZE = 128\nGRAD_CLIP = 10.0\nPOLYAK_TAU = 0.005\n\n# Kesif (karar sayisina gore lineer duser)\nEPSILON_START = 1.0\nEPSILON_MIN = 0.05\nEPSILON_DECAY_DECISIONS = 20_000\nEVAL_EPSILON = 0.0\n# Rastgele kesifte "keep" secme olasiligi. Bu politika kurali degil,\n# yalnizca kesif dagilimidir: tamamen rastgele rol degisimi agi cok\n# erken kopardigi icin keep agirlikli kesif daha anlamli ornek uretir.\nEXPLORE_KEEP_PROB = 0.5\n\n# Karar zamanlamasi ve bolum\nMAX_DECISION_INTERVAL = 20\nMAX_EPISODE_STEPS = 4_000\nMARGIN_ALARM_RATIO = 0.9\n\n# Odul\nREWARD_VISIT = 1.0\nREWARD_SUCCESS = 5.0\nSTEP_COST = 0.002\nDISCONNECT_BASE_PENALTY = 2.0\nUSE_MARGIN_COST = False  # ablation: True/False iki versiyonu karsilastir\nMARGIN_COST = 0.01\n\n# Gozlem\nK_NEAREST_UAVS = 4\nK_NEAREST_GOALS = 6\nREL_CLIP = 6.0\nROLE_TIME_CAP = 200\n\nROLES = ("Free", "Leader", "Slave", "Relay")\nCANDIDATE_KINDS = ("keep", "free", "leader", "slave", "relay")\n# engine._apply_plan isleme sirasi: free_uav_ids -> goal -> relay -> slave\nAPPLY_STAGE = {"free": 0, "leader": 1, "relay": 2, "slave": 3}\n\n_UAV_BLOCK = 14\n_GOAL_BLOCK = 8\nOBS_DIM = (\n    8                       # genel\n    + len(ROLES) + 1 + 2 + 3  # kendi rol, roldeki sure, hareket, ag bilgisi\n    + 4                     # kendi hedef noktasi\n    + 4                     # ground\n    + 2                     # diger drone\'larin merkezi\n    + K_NEAREST_UAVS * _UAV_BLOCK\n    + K_NEAREST_GOALS * _GOAL_BLOCK\n    + 3                     # kalan hedeflerin merkezi + sayisi\n)\nCAND_DIM = len(CANDIDATE_KINDS) + 1 + 4 + 2 + 10 + 1\n\nCandidate = Tuple[str, Optional[int]]\n\n\n# ====================================================================== #\n# Odul                                                                   #\n# ====================================================================== #\n\ndef step_reward(\n    new_visits: int,\n    remaining_goals: int,\n    disconnected: bool,\n    success: bool,\n    bottleneck_ratio: float,\n) -> float:\n    if new_visits < 0 or remaining_goals < 0:\n        raise ValueError("new_visits ve remaining_goals negatif olamaz.")\n\n    reward = -STEP_COST + REWARD_VISIT * new_visits\n\n    if USE_MARGIN_COST and bottleneck_ratio > MARGIN_ALARM_RATIO:\n        reward -= MARGIN_COST\n\n    if disconnected:\n        # Kalan potansiyel odulden buyuk olmali, yoksa erken kopma\n        # gelecekteki adim maliyetinden kacmanin yolu olur.\n        reward -= (\n            DISCONNECT_BASE_PENALTY\n            + REWARD_VISIT * remaining_goals\n            + REWARD_SUCCESS\n        )\n    elif success:\n        reward += REWARD_SUCCESS\n\n    return float(reward)\n\n\n# ====================================================================== #\n# Graf yardimcilari                                                      #\n# ====================================================================== #\n\ndef normalize_role(state: str) -> str:\n    if state in ("Leader", "Ground_Leader"):\n        return "Leader"\n    if state in ROLES:\n        return state\n    return "Free"\n\n\ndef pairwise_distances(points: np.ndarray) -> np.ndarray:\n    points = np.asarray(points, dtype=np.float64).reshape(-1, 2)\n    diff = points[:, None, :] - points[None, :, :]\n    return np.sqrt((diff ** 2).sum(-1))\n\n\ndef bottleneck_edge(dist: np.ndarray) -> Tuple[float, int, int]:\n    """Minimum yayilan agacin en uzun kenari (agin en zayif halkasi).\n    Ag, esik bu degerden buyuk/esitse baglidir."""\n    n = dist.shape[0]\n    if n < 2:\n        return 0.0, -1, -1\n    in_tree = np.zeros(n, dtype=bool)\n    in_tree[0] = True\n    best = dist[0].astype(np.float64).copy()\n    parent = np.zeros(n, dtype=np.int64)\n    worst, wa, wb = 0.0, -1, -1\n    for _ in range(n - 1):\n        masked = np.where(in_tree, np.inf, best)\n        j = int(np.argmin(masked))\n        if masked[j] > worst:\n            worst, wa, wb = float(masked[j]), int(parent[j]), j\n        in_tree[j] = True\n        update = (~in_tree) & (dist[j] < best)\n        best[update] = dist[j][update]\n        parent[update] = j\n    return worst, wa, wb\n\n\ndef connected_without(dist: np.ndarray, thr: float, removed: int) -> bool:\n    nodes = [k for k in range(dist.shape[0]) if k != removed]\n    if len(nodes) <= 1:\n        return True\n    seen = {nodes[0]}\n    stack = [nodes[0]]\n    while stack:\n        a = stack.pop()\n        for b in nodes:\n            if b not in seen and dist[a, b] <= thr:\n                seen.add(b)\n                stack.append(b)\n    return len(seen) == len(nodes)\n\n\ndef compute_relay_point(\n    node_pos: np.ndarray, leader_idx: int, exclude: Set[int]\n) -> np.ndarray:\n    """Lider ile, liderin ekibi disindaki en yakin ag dugumunun orta noktasi."""\n    leader_pos = node_pos[leader_idx]\n    best_idx, best_d = None, np.inf\n    for j in range(node_pos.shape[0]):\n        if j == leader_idx or j in exclude:\n            continue\n        d = float(np.linalg.norm(node_pos[j] - leader_pos))\n        if d < best_d:\n            best_idx, best_d = j, d\n    if best_idx is None:\n        return leader_pos.copy()\n    return (leader_pos + node_pos[best_idx]) / 2.0\n\n\ndef _onehot(value: str, options: Sequence[str]) -> List[float]:\n    return [float(value == o) for o in options]\n\n\n# ====================================================================== #\n# Dunya gorunumu: egosentrik gozlem, adaylar, sanal rol guncellemesi     #\n# ====================================================================== #\n\nclass WorldView:\n    """Bir karar turunda kullanilan anlik goruntu.\n\n    Konumlar sabittir. Roller sanaldir: ayni turda once karar veren\n    drone\'un secimi sonrakilerin gozleminde gorunur (haberlesme yok,\n    ortak gozlem var).\n    """\n\n    def __init__(\n        self,\n        context,\n        motions: Dict[int, Tuple[float, float]],\n        role_since: Dict[int, int],\n        step: int,\n        max_steps: Optional[int],\n    ) -> None:\n        self.thr = float(context.comm_thr) if context.comm_thr > 0 else 1.0\n        self.step = int(step)\n        self.max_steps = max_steps\n        self.role_since = role_since\n\n        uavs = list(context.uavs)\n        self.uav_ids: List[int] = [u.id for u in uavs]\n        self.index = {uid: i for i, uid in enumerate(self.uav_ids)}\n        self.n_uavs = len(uavs)\n        self.speed = float(np.mean([u.speed for u in uavs])) if uavs else 1.0\n\n        self.role: Dict[int, str] = {}\n        self.target: Dict[int, Optional[int]] = {}\n        self.leader: Dict[int, Optional[int]] = {}\n        self.relay_point: Dict[int, Optional[np.ndarray]] = {}\n        self.motion: Dict[int, Tuple[float, float]] = {}\n        for u in uavs:\n            role = normalize_role(u.state)\n            self.role[u.id] = role\n            self.target[u.id] = u.target_goal_id if role == "Leader" else None\n            self.leader[u.id] = (\n                u.leader_id if role in ("Slave", "Relay") else None\n            )\n            # Rolu Relay olmayan drone\'un relay_target\'i bayattir, yok sayilir.\n            self.relay_point[u.id] = (\n                np.array([u.relay_target.x, u.relay_target.y], dtype=np.float64)\n                if role == "Relay" and u.relay_target is not None\n                else None\n            )\n            self.motion[u.id] = motions.get(u.id, (0.0, 0.0))\n\n        goals = list(context.goals)\n        self.goal_ids: List[int] = [g.id for g in goals]\n        self.goal_index = {gid: i for i, gid in enumerate(self.goal_ids)}\n        self.goal_pos = np.array(\n            [[g.position.x, g.position.y] for g in goals], dtype=np.float64\n        ).reshape(-1, 2)\n        self.goal_state: Dict[int, str] = {g.id: g.state for g in goals}\n\n        uav_pos = np.array(\n            [[u.position.x, u.position.y] for u in uavs], dtype=np.float64\n        ).reshape(-1, 2)\n        self.has_ground = context.ground is not None\n        if self.has_ground:\n            ground = np.array(\n                [[context.ground.position.x, context.ground.position.y]],\n                dtype=np.float64,\n            )\n            self.node_pos = np.vstack([uav_pos, ground])\n            self.ground_index: Optional[int] = self.n_uavs\n        else:\n            self.node_pos = uav_pos\n            self.ground_index = None\n        self.uav_pos = self.node_pos[: self.n_uavs]\n\n        self.node_dist = pairwise_distances(self.node_pos)\n        b, a, c = bottleneck_edge(self.node_dist)\n        self.bottleneck_ratio = b / self.thr\n        self.bottleneck_nodes = {a, c}\n        connected = b <= self.thr\n        self.articulation = {\n            uid: bool(\n                connected\n                and self.node_pos.shape[0] > 2\n                and not connected_without(self.node_dist, self.thr, i)\n            )\n            for uid, i in self.index.items()\n        }\n\n        if self.goal_pos.shape[0] and self.node_pos.shape[0]:\n            diff = self.goal_pos[:, None, :] - self.node_pos[None, :, :]\n            self.goal_node_dist = np.sqrt((diff ** 2).sum(-1))\n        else:\n            self.goal_node_dist = np.zeros(\n                (self.goal_pos.shape[0], self.node_pos.shape[0])\n            )\n        self.goal_goal_dist = pairwise_distances(self.goal_pos)\n\n        self.new_this_round: Set[int] = set()\n        self.round_kind: Dict[int, str] = {}\n        self.released_goals: Set[int] = set()\n\n    # ------------------------------------------------------------------ #\n    # Kucuk yardimcilar                                                  #\n    # ------------------------------------------------------------------ #\n\n    def _rel(self, origin: np.ndarray, point: np.ndarray) -> List[float]:\n        d = point - origin\n        dist = float(np.hypot(d[0], d[1]))\n        return [\n            float(np.clip(d[0] / self.thr, -REL_CLIP, REL_CLIP)),\n            float(np.clip(d[1] / self.thr, -REL_CLIP, REL_CLIP)),\n            float(min(dist / self.thr, REL_CLIP)),\n        ]\n\n    def _point_block(self, origin: np.ndarray, point) -> List[float]:\n        if point is None:\n            return [0.0, 0.0, 0.0, 0.0]\n        return [1.0, *self._rel(origin, point)]\n\n    def _time_in_role(self, uid: int) -> float:\n        since = self.role_since.get(uid, self.step)\n        return float(min(max(self.step - since, 0), ROLE_TIME_CAP)) / ROLE_TIME_CAP\n\n    def _unvisited(self) -> List[int]:\n        return [g for g in self.goal_ids if self.goal_state[g] != "Visited"]\n\n    def _goal_dist_excluding(self, gi: int, node_idx: int) -> float:\n        cols = [j for j in range(self.node_pos.shape[0]) if j != node_idx]\n        if not cols:\n            return REL_CLIP\n        return float(min(self.goal_node_dist[gi, cols].min() / self.thr, REL_CLIP))\n\n    def _nearest_other_goal(self, gi: int) -> float:\n        others = [\n            self.goal_index[g]\n            for g in self._unvisited()\n            if self.goal_index[g] != gi\n        ]\n        if not others:\n            return REL_CLIP\n        return float(min(self.goal_goal_dist[gi, others].min() / self.thr, REL_CLIP))\n\n    def _follower_count(self, uid: int) -> int:\n        return sum(\n            1\n            for x in self.uav_ids\n            if self.role[x] in ("Slave", "Relay") and self.leader[x] == uid\n        )\n\n    def current_target_point(self, uid: int) -> Optional[np.ndarray]:\n        role = self.role[uid]\n        if role == "Leader":\n            g = self.target[uid]\n            if g in self.goal_index:\n                return self.goal_pos[self.goal_index[g]]\n        elif role == "Slave":\n            leader = self.leader[uid]\n            if leader in self.index:\n                return self.uav_pos[self.index[leader]]\n        elif role == "Relay":\n            if self.relay_point[uid] is not None:\n                return self.relay_point[uid]\n            leader = self.leader[uid]\n            if leader in self.index:\n                return self.uav_pos[self.index[leader]]\n        return None\n\n    def _would_cycle(self, uid: int, candidate_leader: int) -> bool:\n        x: Optional[int] = candidate_leader\n        seen: Set[int] = set()\n        while x is not None and x not in seen:\n            if x == uid:\n                return True\n            seen.add(x)\n            x = self.leader[x] if self.role.get(x) in ("Slave", "Relay") else None\n        return False\n\n    # ------------------------------------------------------------------ #\n    # Gozlem                                                             #\n    # ------------------------------------------------------------------ #\n\n    def observation(self, uid: int) -> np.ndarray:\n        i = self.index[uid]\n        me = self.uav_pos[i]\n        unvisited = self._unvisited()\n        n_goals = len(self.goal_ids)\n\n        f: List[float] = [\n            1.0 - len(unvisited) / n_goals if n_goals else 1.0,\n            min(len(unvisited), 20) / 20.0,\n            min(self.n_uavs, 10) / 10.0,\n            float(self.has_ground),\n            float(min(self.bottleneck_ratio, 3.0)),\n            float(self.bottleneck_ratio > MARGIN_ALARM_RATIO),\n            self.speed / self.thr,\n            (self.step / self.max_steps) if self.max_steps else 0.0,\n        ]\n\n        f += _onehot(self.role[uid], ROLES)\n        f.append(self._time_in_role(uid))\n        sp = max(self.speed, 1e-6)\n        mx, my = self.motion[uid]\n        f += [float(np.clip(mx / sp, -1, 1)), float(np.clip(my / sp, -1, 1))]\n        others_nodes = [j for j in range(self.node_pos.shape[0]) if j != i]\n        f.append(\n            float(min(self.node_dist[i, others_nodes].min() / self.thr, REL_CLIP))\n            if others_nodes\n            else REL_CLIP\n        )\n        f.append(float(i in self.bottleneck_nodes))\n        f.append(float(self.articulation[uid]))\n\n        f += self._point_block(me, self.current_target_point(uid))\n        f += self._point_block(\n            me,\n            self.node_pos[self.ground_index] if self.ground_index is not None else None,\n        )\n\n        other_uavs = [v for v in self.uav_ids if v != uid]\n        if other_uavs:\n            centroid = self.uav_pos[[self.index[v] for v in other_uavs]].mean(0)\n            f += self._rel(me, centroid)[:2]\n        else:\n            f += [0.0, 0.0]\n\n        other_uavs.sort(key=lambda v: self.node_dist[i, self.index[v]])\n        for k in range(K_NEAREST_UAVS):\n            if k < len(other_uavs):\n                f += self._uav_block(uid, me, other_uavs[k])\n            else:\n                f += [0.0] * _UAV_BLOCK\n\n        unvisited.sort(key=lambda g: self.goal_node_dist[self.goal_index[g], i])\n        for k in range(K_NEAREST_GOALS):\n            if k < len(unvisited):\n                f += self._goal_block(uid, i, me, unvisited[k])\n            else:\n                f += [0.0] * _GOAL_BLOCK\n\n        rest = unvisited[K_NEAREST_GOALS:]\n        if rest:\n            centroid = self.goal_pos[[self.goal_index[g] for g in rest]].mean(0)\n            f += self._rel(me, centroid)[:2]\n            f.append(min(len(rest), 20) / 20.0)\n        else:\n            f += [0.0, 0.0, 0.0]\n\n        arr = np.asarray(f, dtype=np.float32)\n        if arr.shape[0] != OBS_DIM:\n            raise RuntimeError(f"Gozlem boyutu {arr.shape[0]} != {OBS_DIM}")\n        return arr\n\n    def _uav_block(self, uid: int, me: np.ndarray, v: int) -> List[float]:\n        j = self.index[v]\n        f = [1.0, *self._rel(me, self.uav_pos[j])]\n        f += _onehot(self.role[v], ROLES)\n        f.append(float(self.leader[v] == uid))\n        f.append(float(self.leader[uid] == v))\n        f += self._point_block(me, self.current_target_point(v))\n        return f\n\n    def _goal_block(self, uid: int, i: int, me: np.ndarray, g: int) -> List[float]:\n        gi = self.goal_index[g]\n        f = [1.0, *self._rel(me, self.goal_pos[gi])]\n        f.append(float(self.goal_state[g] == "Assigned"))\n        f.append(float(self.role[uid] == "Leader" and self.target[uid] == g))\n        f.append(self._goal_dist_excluding(gi, i))\n        uav_d = self.goal_node_dist[gi, : self.n_uavs]\n        f.append(float(self.n_uavs > 0 and int(np.argmin(uav_d)) == i))\n        return f\n\n    # ------------------------------------------------------------------ #\n    # Adaylar                                                            #\n    # ------------------------------------------------------------------ #\n\n    def candidates(self, uid: int) -> List[Candidate]:\n        out: List[Candidate] = []\n        role = self.role[uid]\n        if role != "Free":\n            out.append(("keep", None))\n        out.append(("free", None))\n\n        for g in self.goal_ids:\n            # Ayni turda serbest birakilan hedef bu turda yeniden atanmaz:\n            # motorun atamalari isleme sirasi gorulmedi, yarisa girmesin.\n            if (\n                self.goal_state[g] == "Free"\n                and g not in self.released_goals\n                and g != self.target[uid]\n            ):\n                out.append(("leader", g))\n\n        for v in self.uav_ids:\n            if v == uid or self._would_cycle(uid, v):\n                continue\n            if not (role == "Slave" and self.leader[uid] == v):\n                out.append(("slave", v))\n            # Bu turda Slave olan drone\'a Relay atanamaz: motor relay\'i\n            # slave\'den once isler, liderin _free_uav\'i relay\'i hemen dusurur.\n            if (\n                not (role == "Relay" and self.leader[uid] == v)\n                and self.round_kind.get(v) != "slave"\n            ):\n                out.append(("relay", v))\n        return out\n\n    def candidate_features(self, uid: int, cand: Candidate) -> np.ndarray:\n        kind, ref = cand\n        i = self.index[uid]\n        me = self.uav_pos[i]\n        cur = self.role[uid]\n\n        f = _onehot(kind, CANDIDATE_KINDS)\n        changed = not (kind == "keep" or (kind == "free" and cur == "Free"))\n        f.append(float(changed))\n\n        if kind == "keep":\n            point = self.current_target_point(uid)\n        elif kind == "leader":\n            point = self.goal_pos[self.goal_index[ref]]\n        elif kind in ("slave", "relay"):\n            point = self.uav_pos[self.index[ref]]\n        else:\n            point = None\n        f += self._point_block(me, point)\n\n        if kind == "leader":\n            gi = self.goal_index[ref]\n            f.append(self._goal_dist_excluding(gi, i))\n            f.append(self._nearest_other_goal(gi))\n        else:\n            f += [0.0, 0.0]\n\n        if kind in ("slave", "relay"):\n            f += _onehot(self.role[ref], ROLES)\n            f.append(float(self.leader[ref] == uid))\n            f.append(min(self._follower_count(ref), 4) / 4.0)\n            f += self._point_block(me, self.current_target_point(ref))\n        else:\n            f += [0.0] * 10\n\n        f.append(self._time_in_role(uid) if kind == "keep" else 0.0)\n\n        arr = np.asarray(f, dtype=np.float32)\n        if arr.shape[0] != CAND_DIM:\n            raise RuntimeError(f"Aday boyutu {arr.shape[0]} != {CAND_DIM}")\n        return arr\n\n    # ------------------------------------------------------------------ #\n    # Sanal uygulama (motoru taklit eder)                                #\n    # ------------------------------------------------------------------ #\n\n    def _release(self, uid: int, new_kind: str) -> None:\n        g = self.target[uid]\n        if g is not None and self.goal_state.get(g) == "Assigned":\n            self.goal_state[g] = "Free"\n            self.released_goals.add(g)\n        self.target[uid] = None\n        self.leader[uid] = None\n        self.relay_point[uid] = None\n        self.role[uid] = "Free"\n        # Motor: _free_uav -> delete_my_slave_list. Relay\'ler de liderin\n        # my_slave_list\'inde tutuldugu icin Slave ve Relay birlikte dagilir.\n        # Bu turda yeni atanmis takipci, motor onun atamasini liderin\n        # atamasindan sonra isleyecekse korunur.\n        new_stage = APPLY_STAGE[new_kind]\n        for x in self.uav_ids:\n            if self.role[x] not in ("Slave", "Relay") or self.leader[x] != uid:\n                continue\n            if (\n                x in self.new_this_round\n                and APPLY_STAGE[self.round_kind[x]] > new_stage\n            ):\n                continue\n            self.role[x] = "Free"\n            self.leader[x] = None\n            self.relay_point[x] = None\n\n    def apply(self, uid: int, cand: Candidate) -> bool:\n        kind, ref = cand\n        if kind == "keep":\n            return False\n        if kind == "free" and self.role[uid] == "Free":\n            return False\n\n        self._release(uid, kind)\n        if kind == "leader":\n            self.role[uid] = "Leader"\n            self.target[uid] = ref\n            self.goal_state[ref] = "Assigned"\n        elif kind == "slave":\n            self.role[uid] = "Slave"\n            self.leader[uid] = ref\n        elif kind == "relay":\n            self.role[uid] = "Relay"\n            self.leader[uid] = ref\n            leader_idx = self.index[ref]\n            exclude = {self.index[uid]} | {\n                self.index[x]\n                for x in self.uav_ids\n                if self.role[x] in ("Slave", "Relay") and self.leader[x] == ref\n            }\n            self.relay_point[uid] = compute_relay_point(\n                self.node_pos, leader_idx, exclude\n            )\n        self.new_this_round.add(uid)\n        self.round_kind[uid] = kind\n        return True\n\n\n# ====================================================================== #\n# Ag                                                                     #\n# ====================================================================== #\n\nclass CandidateQNet(nn.Module):\n    """Q(gozlem, aday). Cikis (B, C)."""\n\n    def __init__(self, obs_dim: int, cand_dim: int, hidden: int = HIDDEN_SIZE):\n        super().__init__()\n        self.obs_enc = nn.Sequential(\n            nn.Linear(obs_dim, hidden), nn.LayerNorm(hidden), nn.ReLU()\n        )\n        self.cand_enc = nn.Sequential(\n            nn.Linear(cand_dim, hidden), nn.LayerNorm(hidden), nn.ReLU()\n        )\n        self.head = nn.Sequential(\n            nn.Linear(2 * hidden, hidden),\n            nn.LayerNorm(hidden),\n            nn.ReLU(),\n            nn.Linear(hidden, 1),\n        )\n\n    def forward(self, obs: torch.Tensor, cands: torch.Tensor) -> torch.Tensor:\n        o = self.obs_enc(obs).unsqueeze(1).expand(-1, cands.shape[1], -1)\n        c = self.cand_enc(cands)\n        return self.head(torch.cat([o, c], dim=-1)).squeeze(-1)\n\n\n# ====================================================================== #\n# Replay                                                                 #\n# ====================================================================== #\n\n@dataclass(frozen=True)\nclass Transition:\n    obs: np.ndarray\n    cand_feats: np.ndarray\n    action: int\n    reward: float      # karar suresince gamma^i ile indirimli toplam\n    discount: float    # gamma^k\n    done: bool         # yalnizca gercek terminal (kopma/basari)\n    next_obs: Optional[np.ndarray]\n    next_cand_feats: Optional[np.ndarray]\n\n\nclass ReplayBuffer:\n    def __init__(self, capacity: int) -> None:\n        self.capacity = int(capacity)\n        self._data: List[Transition] = []\n        self._pos = 0\n\n    def __len__(self) -> int:\n        return len(self._data)\n\n    def append(self, t: Transition) -> None:\n        if len(self._data) < self.capacity:\n            self._data.append(t)\n        else:\n            self._data[self._pos] = t\n            self._pos = (self._pos + 1) % self.capacity\n\n    def sample(self, n: int, rng: random.Random) -> List[Transition]:\n        return rng.sample(self._data, n)\n\n\ndef _collate(batch: List[Transition]):\n    b = len(batch)\n    obs = np.stack([t.obs for t in batch]).astype(np.float32)\n\n    cmax = max(t.cand_feats.shape[0] for t in batch)\n    cands = np.zeros((b, cmax, CAND_DIM), dtype=np.float32)\n    for k, t in enumerate(batch):\n        cands[k, : t.cand_feats.shape[0]] = t.cand_feats\n\n    actions = np.array([t.action for t in batch], dtype=np.int64)\n    rewards = np.array([t.reward for t in batch], dtype=np.float32)\n    discounts = np.array([t.discount for t in batch], dtype=np.float32)\n    dones = np.array(\n        [float(t.done or t.next_obs is None) for t in batch], dtype=np.float32\n    )\n\n    ncmax = max(\n        t.next_cand_feats.shape[0]\n        if (not t.done and t.next_cand_feats is not None)\n        else 1\n        for t in batch\n    )\n    next_obs = np.zeros((b, OBS_DIM), dtype=np.float32)\n    next_cands = np.zeros((b, ncmax, CAND_DIM), dtype=np.float32)\n    next_mask = np.zeros((b, ncmax), dtype=bool)\n    for k, t in enumerate(batch):\n        if t.done or t.next_obs is None or t.next_cand_feats is None:\n            next_mask[k, 0] = True  # kukla aday; (1 - done) ile sifirlanir\n            continue\n        c = t.next_cand_feats.shape[0]\n        next_obs[k] = t.next_obs\n        next_cands[k, :c] = t.next_cand_feats\n        next_mask[k, :c] = True\n\n    return tuple(\n        torch.as_tensor(x)\n        for x in (\n            obs, cands, actions, rewards, discounts, dones,\n            next_obs, next_cands, next_mask,\n        )\n    )\n\n\n# ====================================================================== #\n# Ajan                                                                   #\n# ====================================================================== #\n\nclass SharedAgent:\n    def __init__(self, seed: Optional[int] = None) -> None:\n        if seed is not None:\n            torch.manual_seed(seed)\n        self.rng = random.Random(seed)\n\n        self.online = CandidateQNet(OBS_DIM, CAND_DIM, HIDDEN_SIZE)\n        self.target = copy.deepcopy(self.online)\n        for p in self.target.parameters():\n            p.requires_grad_(False)\n        self.optimizer = torch.optim.AdamW(\n            self.online.parameters(), lr=LR, weight_decay=WEIGHT_DECAY\n        )\n        self.memory = ReplayBuffer(MAX_MEMORY)\n\n        self.decisions = 0\n        self.transitions = 0\n        self.updates = 0\n        self.episodes = 0\n        self.best_avg = float("-inf")\n        self.last_loss: Optional[float] = None\n\n    @property\n    def epsilon(self) -> float:\n        frac = min(self.decisions / max(EPSILON_DECAY_DECISIONS, 1), 1.0)\n        return max(EPSILON_MIN, EPSILON_START - (EPSILON_START - EPSILON_MIN) * frac)\n\n    def select_action(\n        self,\n        obs: np.ndarray,\n        cand_feats: np.ndarray,\n        explore: bool,\n        keep_index: Optional[int] = None,\n    ) -> int:\n        n = cand_feats.shape[0]\n        eps = self.epsilon if explore else EVAL_EPSILON\n        if explore:\n            self.decisions += 1\n        if n == 1:\n            return 0\n        if self.rng.random() < eps:\n            if keep_index is not None and self.rng.random() < EXPLORE_KEEP_PROB:\n                return keep_index\n            return self.rng.randrange(n)\n        with torch.no_grad():\n            q = self.online(\n                torch.as_tensor(obs, dtype=torch.float32).unsqueeze(0),\n                torch.as_tensor(cand_feats, dtype=torch.float32).unsqueeze(0),\n            )[0]\n        return int(torch.argmax(q).item())\n\n    def push(self, transition: Transition) -> None:\n        self.memory.append(transition)\n        self.transitions += 1\n        self.maybe_train()\n\n    def maybe_train(self) -> None:\n        if len(self.memory) < max(MIN_REPLAY_SIZE, BATCH_SIZE):\n            return\n        if self.transitions % TRAIN_EVERY_TRANSITIONS != 0:\n            return\n        self._train_step()\n\n    def _train_step(self) -> None:\n        batch = self.memory.sample(BATCH_SIZE, self.rng)\n        (obs, cands, actions, rewards, discounts, dones,\n         next_obs, next_cands, next_mask) = _collate(batch)\n\n        q = self.online(obs, cands).gather(1, actions.unsqueeze(1)).squeeze(1)\n\n        with torch.no_grad():\n            next_online = self.online(next_obs, next_cands).masked_fill(\n                ~next_mask, float("-inf")\n            )\n            next_action = next_online.argmax(dim=1, keepdim=True)\n            next_q = self.target(next_obs, next_cands).gather(1, next_action).squeeze(1)\n            y = rewards + discounts * (1.0 - dones) * next_q\n\n        loss = F.smooth_l1_loss(q, y)\n        self.optimizer.zero_grad(set_to_none=True)\n        loss.backward()\n        nn.utils.clip_grad_norm_(self.online.parameters(), GRAD_CLIP)\n        self.optimizer.step()\n\n        with torch.no_grad():\n            for p, tp in zip(self.online.parameters(), self.target.parameters()):\n                tp.mul_(1.0 - POLYAK_TAU).add_(p, alpha=POLYAK_TAU)\n\n        self.updates += 1\n        self.last_loss = float(loss.item())\n\n    # ------------------------------------------------------------------ #\n    # Kayit / yukleme                                                    #\n    # ------------------------------------------------------------------ #\n\n    def save(self, path: str) -> None:\n        folder = os.path.dirname(path)\n        if folder:\n            os.makedirs(folder, exist_ok=True)\n        payload = {\n            "observation_version": OBSERVATION_VERSION,\n            "training_config_version": TRAINING_CONFIG_VERSION,\n            "obs_dim": OBS_DIM,\n            "cand_dim": CAND_DIM,\n            "hidden_size": HIDDEN_SIZE,\n            "gamma": GAMMA,\n            "online": self.online.state_dict(),\n            "target": self.target.state_dict(),\n            "optimizer": self.optimizer.state_dict(),\n            "decisions": self.decisions,\n            "transitions": self.transitions,\n            "updates": self.updates,\n            "episodes": self.episodes,\n            "best_avg": self.best_avg,\n        }\n        tmp = path + ".tmp"\n        torch.save(payload, tmp)\n        os.replace(tmp, path)\n\n    def load(self, path: str) -> None:\n        if not os.path.exists(path):\n            raise ValueError(f"Checkpoint bulunamadi: {path}")\n        try:\n            try:\n                payload = torch.load(path, map_location="cpu", weights_only=False)\n            except TypeError:\n                payload = torch.load(path, map_location="cpu")\n        except Exception as exc:\n            raise ValueError(f"Checkpoint okunamadi: {exc}") from exc\n\n        if not isinstance(payload, dict):\n            raise ValueError("Checkpoint bicimi gecersiz.")\n        expected = {\n            "observation_version": OBSERVATION_VERSION,\n            "obs_dim": OBS_DIM,\n            "cand_dim": CAND_DIM,\n            "hidden_size": HIDDEN_SIZE,\n        }\n        for key, value in expected.items():\n            if payload.get(key) != value:\n                raise ValueError(\n                    f"Checkpoint uyumsuz: {key}={payload.get(key)} (beklenen {value})"\n                )\n        if abs(float(payload.get("gamma", -1.0)) - GAMMA) > 1e-9:\n            raise ValueError("Checkpoint gamma degeri farkli, yuklenmedi.")\n\n        try:\n            self.online.load_state_dict(payload["online"])\n            self.target.load_state_dict(payload["target"])\n            if payload.get("training_config_version") == TRAINING_CONFIG_VERSION:\n                self.optimizer.load_state_dict(payload["optimizer"])\n                self.decisions = int(payload.get("decisions", 0))\n                self.transitions = int(payload.get("transitions", 0))\n                self.updates = int(payload.get("updates", 0))\n                self.episodes = int(payload.get("episodes", 0))\n                self.best_avg = float(payload.get("best_avg", float("-inf")))\n        except Exception as exc:\n            raise ValueError(f"Checkpoint agirliklari yuklenemedi: {exc}") from exc\n',
    'simulation_core/engine.py': '"""Core simulation engine for heterogeneous UAV networks.\n\nThis module provides the main SimulationEngine class that orchestrates\nsimulation execution, manages entities (UAVs, goals, ground stations),\nand executes routing algorithms.\n\nClasses:\n    SimulationEngine: Main simulation engine coordinating all simulation aspects.\n\nExample:\n    >>> from simulation_core import SimulationEngine\n    >>> engine = SimulationEngine()\n    >>> engine.add_goal(500, 500)\n    >>> engine.generate_ground(0, 0)\n    >>> # Add UAVs and step through simulation\n    >>> engine.step()\n"""\n\nfrom __future__ import annotations\n\nimport random\nimport time\nfrom typing import Callable, Dict, List, Optional, Type\n\nfrom simulation_app.domain.goal import Goal\nfrom simulation_app.domain.ground import Ground\nfrom simulation_app.domain.uav import UAV\nfrom simulation_app.support.distance import Distance\nfrom simulation_core.algorithm_api import (\n    AlgorithmPlan,\n    GoalAssignment,\n    GoalView,\n    GroundView,\n    Position,\n    RelayAssignment,\n    SimulationContext,\n    SlaveAssignment,\n    UavView,\n)\nfrom simulation_core.config import SimulationConfig\nfrom simulation_core.environment import SimulationEnvironment\nfrom simulation_core.registry import AlgorithmRegistry\nfrom simulation_core.slow_zones import (\n    SlowZone,\n    SlowZoneConfig,\n    generate_slow_zones,\n    speed_factor_at,\n)\n\n\nclass SimulationEngine:\n    def __init__(self, comm_thr: float = 200, algorithm_name: Optional[str] = None):\n        self.environment = SimulationEnvironment(comm_thr=comm_thr)\n        self.algorithm_registry = AlgorithmRegistry()\n        self.algorithm = self.algorithm_registry.create(\n            algorithm_name or self.algorithm_registry.default_name()\n        )\n        self.config_provider: Callable[[], SimulationConfig] = lambda: SimulationConfig()\n        self.simulation_running = False\n        self.start_time: Optional[float] = None\n        self.uav_types: Dict[str, Type[UAV]] = {"UAV": UAV}\n        # Yavaslatma bolgeleri: algoritmaya verilmez, yalnizca hareketi etkiler.\n        self.slow_zone_config: Optional[SlowZoneConfig] = None\n        self.slow_zones: List[SlowZone] = []\n\n    @property\n    def goals(self) -> List[Goal]:\n        return self.environment.goals\n\n    @goals.setter\n    def goals(self, value: List[Goal]) -> None:\n        self.environment.goals = value\n\n    @property\n    def uavs(self) -> List[UAV]:\n        return self.environment.uavs\n\n    @uavs.setter\n    def uavs(self, value: List[UAV]) -> None:\n        self.environment.uavs = value\n\n    @property\n    def ground(self) -> Optional[Ground]:\n        return self.environment.ground\n\n    @ground.setter\n    def ground(self, value: Optional[Ground]) -> None:\n        self.environment.ground = value\n\n    @property\n    def comm_thr(self) -> float:\n        return self.environment.comm_thr\n\n    @comm_thr.setter\n    def comm_thr(self, value: float) -> None:\n        self.environment.set_comm_thr(value)\n\n    def register_uav_type(self, uav_cls: Type[UAV]) -> None:\n        self.uav_types[uav_cls.__name__] = uav_cls\n\n    def set_config_provider(self, provider: Callable[[], SimulationConfig]) -> None:\n        self.config_provider = provider\n\n    def get_runtime_config(self) -> SimulationConfig:\n        config = self.config_provider()\n        if isinstance(config, dict):\n            config = SimulationConfig(**config)\n        if not isinstance(config, SimulationConfig):\n            raise TypeError("Config provider must return SimulationConfig or dict.")\n        config.validate()\n        return config\n\n    def get_algorithm_metadata(self):\n        return self.algorithm_registry.metadata()\n\n    def set_algorithm(self, algorithm_name: str) -> None:\n        self.algorithm = self.algorithm_registry.create(algorithm_name)\n        self.algorithm.reset()\n\n    def get_current_algorithm_name(self) -> str:\n        return self.algorithm.name\n\n    # ------------------------------------------------------------------ #\n    # Yavaslatma bolgeleri                                               #\n    # ------------------------------------------------------------------ #\n\n    def set_slow_zone_config(self, config: Optional[SlowZoneConfig]) -> None:\n        if config is not None:\n            config.validate()\n        self.slow_zone_config = config\n        if config is None or not config.enabled:\n            self.slow_zones = []\n\n    def generate_slow_zones(self, seed: Optional[int] = None) -> List[SlowZone]:\n        config = self.slow_zone_config\n        if config is None or not config.enabled:\n            self.slow_zones = []\n        else:\n            rng = random.Random(seed) if seed is not None else random.Random()\n            self.slow_zones = generate_slow_zones(rng, config)\n        return self.slow_zones\n\n    def clear_slow_zones(self) -> None:\n        self.slow_zones = []\n\n    def _speed_factor(self, uav: UAV) -> float:\n        config = self.slow_zone_config\n        if config is None or not config.enabled or not self.slow_zones:\n            return 1.0\n        return speed_factor_at(self.slow_zones, uav.pos.x, uav.pos.y, config.speed_factor)\n\n    # ------------------------------------------------------------------ #\n\n    def add_goal(self, x: int, y: int) -> Goal:\n        return self.environment.add_goal(x, y)\n\n    def generate_ground(self, x: int, y: int) -> Ground:\n        return self.environment.generate_ground(x, y)\n\n    def generate_goals(self, goal_count: int, canvas_width: int, canvas_height: int):\n        return self.environment.generate_goals(goal_count, canvas_width, canvas_height)\n\n    def generate_uavs(self, uav_count: int, canvas_width: int, canvas_height: int):\n        return self.environment.generate_uavs(uav_count, canvas_width, canvas_height)\n\n    def add_uav(self, x: int, y: int, uav_cls: Type[UAV] = UAV, **kwargs) -> UAV:\n        return self.environment.add_uav(x, y, uav_cls=uav_cls, **kwargs)\n\n    def add_existing_uav(self, uav: UAV) -> UAV:\n        return self.environment.add_existing_uav(uav)\n\n    def reset_simulation(self) -> None:\n        self.stop_simulation()\n        self.environment.reset()\n        self.start_time = None\n        self.slow_zones = []\n        self.algorithm.reset()\n\n    def start_simulation(self) -> None:\n        config = self.get_runtime_config()\n        self._apply_runtime_config(config)\n        if (\n            self.slow_zone_config is not None\n            and self.slow_zone_config.enabled\n            and self.slow_zone_config.regenerate_on_start\n        ):\n            self.generate_slow_zones()\n        self.simulation_running = True\n        self.start_time = time.time()\n        self.algorithm.reset()\n\n    def stop_simulation(self) -> None:\n        self.simulation_running = False\n\n    def move_uavs(self) -> Optional[str]:\n        if not self.simulation_running:\n            return None\n\n        config = self.get_runtime_config()\n        self._apply_runtime_config(config)\n        current_time = time.time()\n\n        if config.target_eval_mode == "revisit" and self.start_time is not None:\n            elapsed = current_time - self.start_time\n            if elapsed >= config.simulation_time:\n                self.stop_simulation()\n                return "time_elapsed"\n            self.environment.update_goal_states(current_time, config.threshold1)\n\n        context = self._build_context(current_time, config)\n        plan = self.algorithm.build_plan(context)\n        self._apply_plan(plan)\n        self._advance_uavs(current_time, config)\n        next_context = self._build_context(current_time, config)\n        finish_step = getattr(self.algorithm, "finish_step", None)\n        if finish_step is not None:\n            stop_reason = finish_step(context, next_context)\n            if stop_reason is not None:\n                self.stop_simulation()\n                return stop_reason\n\n        if (\n            config.target_eval_mode == "single_visit"\n            and self.environment.all_goals_visited()\n        ):\n            self.stop_simulation()\n            return "all_goals_visited"\n\n        return None\n\n    def to_dict(self) -> Dict[str, object]:\n        return self.environment.to_dict()\n\n    def load_from_dict(self, data: Dict[str, object]) -> None:\n        self.stop_simulation()\n        self.environment.load_from_dict(data, self.uav_types)\n        self.algorithm.reset()\n\n    def _build_context(\n        self, current_time: float, config: SimulationConfig\n    ) -> SimulationContext:\n        ground = None\n        if self.environment.ground is not None:\n            ground = GroundView(position=Position.from_vector(self.environment.ground.pos))\n\n        uavs = tuple(\n            UavView(\n                id=uav.uav_no,\n                position=Position.from_vector(uav.pos),\n                state=uav.state,\n                uav_type=uav.__class__.__name__,\n                speed=float(getattr(uav, "speed", config.uav_speed)),\n                target_goal_id=uav.target.goal_no if uav.target else None,\n                leader_id=uav.my_leader.uav_no if uav.my_leader else None,\n                relay_target=(\n                    Position.from_vector(uav.target_position)\n                    if hasattr(uav, "target_position")\n                    else None\n                ),\n            )\n            for uav in self.environment.uavs\n        )\n\n        goals = tuple(\n            GoalView(\n                id=goal.goal_no,\n                position=Position.from_vector(goal.pos),\n                state=goal.state,\n                last_visited_time=goal.last_visited_time,\n            )\n            for goal in self.environment.goals\n        )\n\n        return SimulationContext(\n            current_time=current_time,\n            comm_thr=self.environment.comm_thr,\n            config=config,\n            uavs=uavs,\n            goals=goals,\n            ground=ground,\n        )\n\n    def _apply_runtime_config(self, config: SimulationConfig) -> None:\n        for uav in self.environment.uavs:\n            uav.speed = float(config.uav_speed)\n\n    def _apply_plan(self, plan: AlgorithmPlan) -> None:\n        if plan.clear_uav_roles:\n            for uav in self.environment.uavs:\n                self._free_uav(uav)\n        if plan.clear_goal_assignments:\n            for goal in self.environment.goals:\n                self._free_goal(goal)\n\n        for uav_id in plan.free_uav_ids:\n            uav = self._get_uav(uav_id)\n            if uav is not None:\n                self._free_uav(uav)\n\n        for goal_id in plan.free_goal_ids:\n            goal = self._get_goal(goal_id)\n            if goal is not None:\n                self._free_goal(goal)\n\n        for assignment in plan.goal_assignments:\n            self._apply_goal_assignment(assignment)\n\n        for assignment in plan.relay_assignments:\n            self._apply_relay_assignment(assignment)\n\n        for assignment in plan.slave_assignments:\n            self._apply_slave_assignment(assignment)\n\n    def _apply_goal_assignment(self, assignment: GoalAssignment) -> None:\n        uav = self._get_uav(assignment.uav_id)\n        goal = self._get_goal(assignment.goal_id)\n        if uav is None or goal is None:\n            return\n        self._free_uav(uav)\n        self._free_goal(goal)\n        uav.state = assignment.role\n        uav.target = goal\n        goal.state = "Assigned"\n\n    def _apply_relay_assignment(self, assignment: RelayAssignment) -> None:\n        uav = self._get_uav(assignment.uav_id)\n        leader = self._get_uav(assignment.leader_id)\n        if uav is None or leader is None or uav is leader:\n            return\n        self._free_uav(uav)\n        uav.state = "Relay"\n        uav.my_leader = leader\n        uav.target_position = assignment.target_position.to_vector()\n        leader.my_slave_list.add(uav)\n\n    def _apply_slave_assignment(self, assignment: SlaveAssignment) -> None:\n        uav = self._get_uav(assignment.uav_id)\n        leader = self._get_uav(assignment.leader_id)\n        if uav is None or leader is None or uav is leader:\n            return\n        self._free_uav(uav)\n        uav.state = "Slave"\n        uav.my_leader = leader\n        leader.my_slave_list.add(uav)\n\n    def _advance_uavs(self, current_time: float, config: SimulationConfig) -> None:\n        base_speed = float(config.uav_speed)\n        for uav in self.environment.uavs:\n            context = self._build_context(current_time, config)\n            uav_view = context.uav_by_id(uav.uav_no)\n            if uav_view is None:\n                continue\n\n            # Bolge etkisi yalnizca bu hareket icin uygulanir, sonra nominal\n            # hiza donulur: context\'teki speed alani bolge bilgisini sizdirmaz.\n            uav.speed = base_speed * self._speed_factor(uav)\n            try:\n                if uav.state in {"Leader", "Ground_Leader"} and uav.target is not None:\n                    target_position = Position.from_vector(uav.target.pos)\n                    if self.algorithm.allow_movement(context, uav_view, target_position):\n                        uav.move_to_target()\n                elif uav.state == "Relay" and hasattr(uav, "target_position"):\n                    target_position = Position.from_vector(uav.target_position)\n                    if self.algorithm.allow_movement(context, uav_view, target_position):\n                        uav.move_to_position(uav.target_position)\n                    elif uav.my_leader is not None:\n                        leader_position = Position.from_vector(uav.my_leader.pos)\n                        if self.algorithm.allow_movement(context, uav_view, leader_position):\n                            uav.move_to_leader()\n                elif uav.state == "Slave" and uav.my_leader is not None:\n                    if Distance.distance_between(uav, uav.my_leader) > self.environment.comm_thr * 0.8:\n                        leader_position = Position.from_vector(uav.my_leader.pos)\n                        if self.algorithm.allow_movement(context, uav_view, leader_position):\n                            uav.move_to_leader()\n            finally:\n                uav.speed = base_speed\n\n    def _free_uav(self, uav: UAV) -> None:\n        uav.delete_my_slave_list()\n        uav.state = "Free"\n        uav.my_leader = None\n        if uav.target is not None:\n            self._free_goal(uav.target)\n            uav.target = None\n        if hasattr(uav, "target_position"):\n            delattr(uav, "target_position")\n\n    def _free_goal(self, goal: Goal) -> None:\n        if goal.state != "Visited":\n            goal.state = "Free"\n\n    def _get_uav(self, uav_id: int) -> Optional[UAV]:\n        return next((uav for uav in self.environment.uavs if uav.uav_no == uav_id), None)\n\n    def _get_goal(self, goal_id: int) -> Optional[Goal]:\n        return next((goal for goal in self.environment.goals if goal.goal_no == goal_id), None)\n',
    'simulation_core/slow_zones.py': '"""\nYavaslatma bolgeleri.\n\nDaire seklindeki bolgelerin icindeki drone sabit bir oranla yavaslar.\nBolgeler algoritmaya (SimulationContext) hic verilmez; ajan yalnizca\nkendi gerceklesen hareketinden etkisini hissedebilir.\n"""\n\nfrom __future__ import annotations\n\nimport math\nimport random\nfrom dataclasses import dataclass\nfrom typing import List, Sequence\n\n\n@dataclass(frozen=True)\nclass SlowZone:\n    x: float\n    y: float\n    radius: float\n\n    def contains(self, x: float, y: float) -> bool:\n        return math.hypot(x - self.x, y - self.y) <= self.radius\n\n\n@dataclass(frozen=True)\nclass SlowZoneConfig:\n    enabled: bool = True\n    count_min: int = 2\n    count_max: int = 4\n    radius_min: float = 60.0\n    radius_max: float = 140.0\n    speed_factor: float = 0.5\n    canvas_width: int = 960\n    canvas_height: int = 760\n    regenerate_on_start: bool = True\n\n    def validate(self) -> None:\n        if self.count_min < 0 or self.count_max < self.count_min:\n            raise ValueError("Bolge sayisi araligi gecersiz.")\n        if self.radius_min <= 0 or self.radius_max < self.radius_min:\n            raise ValueError("Bolge yaricap araligi gecersiz.")\n        if not 0.0 < self.speed_factor <= 1.0:\n            raise ValueError("Yavaslatma orani (0, 1] araliginda olmali.")\n        if self.canvas_width <= 0 or self.canvas_height <= 0:\n            raise ValueError("Canvas boyutu pozitif olmali.")\n\n\ndef generate_slow_zones(rng: random.Random, config: SlowZoneConfig) -> List[SlowZone]:\n    config.validate()\n    if not config.enabled:\n        return []\n    count = rng.randint(config.count_min, config.count_max)\n    zones: List[SlowZone] = []\n    for _ in range(count):\n        r = rng.uniform(config.radius_min, config.radius_max)\n        x = rng.uniform(0.0, float(config.canvas_width))\n        y = rng.uniform(0.0, float(config.canvas_height))\n        zones.append(SlowZone(x=x, y=y, radius=r))\n    return zones\n\n\ndef speed_factor_at(\n    zones: Sequence[SlowZone], x: float, y: float, factor: float\n) -> float:\n    """Herhangi bir bolgenin icindeyse sabit oran, degilse 1.0 (ust uste binme carpilmaz)."""\n    for zone in zones:\n        if zone.contains(x, y):\n            return factor\n    return 1.0\n',
    'simulation_app/ui/main_window.py': 'import json\nimport queue\nimport tkinter as tk\nfrom tkinter import filedialog, messagebox, ttk\n\n\nfrom algorithms.model import DroneDQNAlgorithm, DroneDQNSlowZoneAlgorithm\nfrom simulation_app.domain.vector import Vector\nfrom simulation_app.hardware.co_drone import CoDroneDependencyError, co_Drone\nfrom simulation_app.hardware.real_drone_thread import RealDroneThread\nfrom simulation_app.support.functions import MatrixOperation\nfrom simulation_app.support.generate_uav import GenerateUAV\nfrom simulation_core.config import SimulationConfig\nfrom simulation_core.engine import SimulationEngine\nfrom simulation_core.slow_zones import SlowZoneConfig\n\n\n# Registry\'de kayitli olmasalar da arayuzun kurabilecegi algoritmalar.\nLOCAL_ALGORITHMS = {\n    cls.name: cls for cls in (DroneDQNAlgorithm, DroneDQNSlowZoneAlgorithm)\n}\nNORMAL_RL_NAME = DroneDQNAlgorithm.name\nZONES_RL_NAME = DroneDQNSlowZoneAlgorithm.name\n\nSLOW_ZONE_FACTOR = 0.5          # bolge icinde hiz carpani (sabit)\nFAST_TRAINING_STEPS_PER_TICK = 25  # hizli egitimde bir cizimde atilan adim\n\nTRAIN_TEXT = "Yapay Zeka Eğit"\nZONE_TRAIN_TEXT = "Bölgeli Yapay Zeka Eğit"\nSTOP_TEXT = "Eğitimi Durdur"\n\n\nclass MainWindow(tk.Tk):\n    def __init__(self):\n        super().__init__()\n        self.title("Heterogeneous Unmanned Network Simulation Environment V01")\n        self.geometry("1381x838")\n        self.resizable(False, False)\n\n\n        self.simulation_engine = SimulationEngine()\n        self.simulation_engine.register_uav_type(co_Drone)\n\n\n        self.real_drone_commands = queue.Queue()\n        self.real_drone_thread = None\n        self.algorithm_name_by_label = {}\n\n\n        self.training_running = False\n        self.training_mode = None  # "normal" | "zones"\n        self.training_uav_count = 0\n        self.training_goal_count = 0\n\n\n        self.initialize_components()\n        self.simulation_engine.set_config_provider(self.build_simulation_config)\n        self.populate_algorithms()\n        self.update_loop()\n\n\n    def initialize_components(self):\n        self.canvas = tk.Canvas(self, width=960, height=760, bg="white")\n        self.canvas.place(x=0, y=0)\n\n\n        self.groupBox1 = tk.Frame(self, borderwidth=2, relief="groove")\n        self.groupBox1.place(x=968, y=0, width=399, height=749)\n\n\n        self.ResetButton = tk.Button(\n            self.groupBox1,\n            text="Reset",\n            font=("Microsoft Sans Serif", 15),\n            command=self.reset_simulation,\n        )\n        self.ResetButton.place(x=306, y=690, width=75, height=35)\n\n\n        self.LoadButton = tk.Button(\n            self.groupBox1,\n            text="Load",\n            font=("Microsoft Sans Serif", 15),\n            command=self.load_from_file,\n        )\n        self.LoadButton.place(x=231, y=690, width=75, height=35)\n\n\n        self.SaveButton = tk.Button(\n            self.groupBox1,\n            text="Save",\n            font=("Microsoft Sans Serif", 15),\n            command=self.save_to_file,\n        )\n        self.SaveButton.place(x=156, y=690, width=75, height=35)\n\n\n        self.groupBox7 = tk.LabelFrame(\n            self.groupBox1,\n            text="Add Goal",\n            font=("Microsoft Sans Serif", 15),\n        )\n        self.groupBox7.place(x=7, y=602, width=385, height=81)\n\n\n        tk.Label(self.groupBox7, text="X").place(x=7, y=15)\n        self.textBox8 = tk.Entry(self.groupBox7)\n        self.textBox8.place(x=42, y=15, width=66)\n\n\n        tk.Label(self.groupBox7, text="Y").place(x=122, y=15)\n        self.textBox7 = tk.Entry(self.groupBox7)\n        self.textBox7.place(x=158, y=15, width=66)\n\n\n        self.GoalAdd = tk.Button(\n            self.groupBox7,\n            text="Add",\n            command=self.add_goal,\n        )\n        self.GoalAdd.place(x=240, y=5, width=114, height=39)\n\n\n        self.groupBox6 = tk.LabelFrame(\n            self.groupBox1,\n            text="Add UAV",\n            font=("Microsoft Sans Serif", 15),\n        )\n        self.groupBox6.place(x=7, y=515, width=385, height=81)\n\n\n        tk.Label(self.groupBox6, text="X").place(x=7, y=15)\n        self.textBox6 = tk.Entry(self.groupBox6)\n        self.textBox6.place(x=42, y=15, width=66)\n\n\n        tk.Label(self.groupBox6, text="Y").place(x=122, y=15)\n        self.textBox5 = tk.Entry(self.groupBox6)\n        self.textBox5.place(x=158, y=15, width=66)\n\n\n        self.UAVAdd = tk.Button(\n            self.groupBox6,\n            text="Add",\n            command=self.add_uav,\n        )\n        self.UAVAdd.place(x=240, y=5, width=114, height=39)\n\n\n        self.ReStartButton = tk.Button(\n            self.groupBox1,\n            text="Restart",\n            font=("Microsoft Sans Serif", 15),\n            command=self.reset_simulation,\n        )\n        self.ReStartButton.place(x=82, y=690, width=75, height=35)\n\n\n        self.StartButton = tk.Button(\n            self.groupBox1,\n            text="Start",\n            font=("Microsoft Sans Serif", 15),\n            command=self.start_simulation,\n        )\n        self.StartButton.place(x=7, y=690, width=75, height=35)\n\n\n        self.groupBox5 = tk.LabelFrame(\n            self.groupBox1,\n            text="Generate Ground",\n            font=("Microsoft Sans Serif", 15),\n        )\n        self.groupBox5.place(x=7, y=427, width=385, height=81)\n\n\n        tk.Label(self.groupBox5, text="X").place(x=7, y=15)\n        self.textBox3 = tk.Entry(self.groupBox5)\n        self.textBox3.place(x=42, y=15, width=66)\n\n\n        tk.Label(self.groupBox5, text="Y").place(x=122, y=15)\n        self.textBox4 = tk.Entry(self.groupBox5)\n        self.textBox4.place(x=158, y=15, width=66)\n\n\n        self.GroundGenerate = tk.Button(\n            self.groupBox5,\n            text="Generate",\n            command=self.generate_ground,\n        )\n        self.GroundGenerate.place(x=240, y=5, width=114, height=39)\n\n\n        self.groupBox4 = tk.LabelFrame(\n            self.groupBox1,\n            text="Generate Goal",\n            font=("Microsoft Sans Serif", 15),\n        )\n        self.groupBox4.place(x=7, y=339, width=385, height=81)\n\n\n        tk.Label(self.groupBox4, text="Goal Number").place(x=7, y=15)\n        self.textBox2 = tk.Entry(self.groupBox4)\n        self.textBox2.place(x=134, y=15, width=98)\n\n\n        self.GoalGenerate = tk.Button(\n            self.groupBox4,\n            text="Generate",\n            command=self.generate_goals,\n        )\n        self.GoalGenerate.place(x=240, y=5, width=114, height=39)\n\n\n        self.groupBox3 = tk.LabelFrame(\n            self.groupBox1,\n            text="Generate UAV",\n            font=("Microsoft Sans Serif", 15),\n        )\n        self.groupBox3.place(x=7, y=252, width=385, height=81)\n\n\n        tk.Label(self.groupBox3, text="UAV Number").place(x=7, y=5)\n        self.textBox1 = tk.Entry(self.groupBox3)\n        self.textBox1.place(x=134, y=5, width=98)\n\n\n        self.use_co_drone_var = tk.BooleanVar(value=False)\n        self.co_drone_check = tk.Checkbutton(\n            self.groupBox3,\n            text="Use CoDrone",\n            variable=self.use_co_drone_var,\n        )\n        self.co_drone_check.place(x=10, y=25)\n\n\n        self.UAVGenerate = tk.Button(\n            self.groupBox3,\n            text="Generate",\n            command=self.generate_uavs,\n        )\n        self.UAVGenerate.place(x=240, y=5, width=114, height=39)\n\n\n        self.groupBox2 = tk.LabelFrame(\n            self.groupBox1,\n            text="Connection Threshold",\n            font=("Microsoft Sans Serif", 15),\n        )\n        self.groupBox2.place(x=7, y=14, width=385, height=100)\n\n\n        tk.Label(self.groupBox2, text="Threshold").place(x=10, y=20)\n        self.threshold_scale = tk.Scale(\n            self.groupBox2,\n            from_=100.0,\n            to=300.0,\n            resolution=0.1,\n            orient="horizontal",\n            length=200,\n            command=self.update_connection_threshold,\n        )\n        self.threshold_scale.set(self.simulation_engine.comm_thr)\n        self.threshold_scale.place(x=100, y=10)\n\n\n        self.groupBox8 = tk.LabelFrame(\n            self.groupBox1,\n            text="Target Evaluation",\n            font=("Microsoft Sans Serif", 15),\n        )\n        self.groupBox8.place(x=7, y=125, width=385, height=120)\n\n\n        self.target_eval_mode = tk.StringVar(value="single_visit")\n\n\n        def update_threshold_entries(*args):\n            state = (\n                "normal"\n                if self.target_eval_mode.get() == "revisit"\n                else "disabled"\n            )\n            self.threshold1_entry.config(state=state)\n            self.threshold2_entry.config(state=state)\n            self.simulation_time_entry.config(state=state)\n\n\n        self.target_eval_mode.trace_add("write", update_threshold_entries)\n\n\n        tk.Radiobutton(\n            self.groupBox8,\n            text="Single Visit",\n            variable=self.target_eval_mode,\n            value="single_visit",\n        ).place(x=10, y=10)\n\n\n        tk.Radiobutton(\n            self.groupBox8,\n            text="Revisit",\n            variable=self.target_eval_mode,\n            value="revisit",\n        ).place(x=150, y=10)\n\n\n        tk.Label(self.groupBox8, text="Algorithm").place(x=10, y=44)\n        self.algorithm_combo = ttk.Combobox(\n            self.groupBox8,\n            state="readonly",\n            width=28,\n        )\n        self.algorithm_combo.place(x=82, y=42)\n        self.algorithm_combo.bind(\n            "<<ComboboxSelected>>",\n            self.on_algorithm_selected,\n        )\n\n\n        tk.Label(self.groupBox8, text="T1").place(x=10, y=80)\n        self.threshold1_entry = tk.Entry(self.groupBox8)\n        self.threshold1_entry.place(x=32, y=80, width=40)\n        self.threshold1_entry.insert(0, "10")\n\n\n        tk.Label(self.groupBox8, text="T2").place(x=82, y=80)\n        self.threshold2_entry = tk.Entry(self.groupBox8)\n        self.threshold2_entry.place(x=104, y=80, width=40)\n        self.threshold2_entry.insert(0, "30")\n\n\n        tk.Label(self.groupBox8, text="Sim Time").place(x=160, y=80)\n        self.simulation_time_entry = tk.Entry(self.groupBox8)\n        self.simulation_time_entry.place(x=226, y=80, width=50)\n        self.simulation_time_entry.insert(0, "100")\n\n\n        tk.Label(self.groupBox8, text="Speed").place(x=286, y=80)\n        self.uav_speed_entry = tk.Entry(self.groupBox8)\n        self.uav_speed_entry.place(x=334, y=80, width=36)\n        self.uav_speed_entry.insert(0, "5")\n\n\n        update_threshold_entries()\n\n\n        self.TrainButton = tk.Button(\n            self.groupBox1,\n            text=TRAIN_TEXT,\n            font=("Microsoft Sans Serif", 10),\n            command=self.toggle_training,\n        )\n        self.TrainButton.place(x=7, y=728, width=385, height=20)\n\n\n        # ------------------------------------------------------------ #\n        # Yavaslatma bolgeleri paneli (canvas\'in altinda)              #\n        # ------------------------------------------------------------ #\n        self.groupBox9 = tk.LabelFrame(\n            self,\n            text="Yavaşlatma Bölgeleri",\n            font=("Microsoft Sans Serif", 13),\n        )\n        self.groupBox9.place(x=7, y=764, width=1360, height=68)\n\n\n        tk.Label(self.groupBox9, text="Sayı").place(x=10, y=8)\n        self.zone_count_min_entry = tk.Entry(self.groupBox9)\n        self.zone_count_min_entry.place(x=48, y=8, width=36)\n        self.zone_count_min_entry.insert(0, "2")\n        tk.Label(self.groupBox9, text="-").place(x=88, y=8)\n        self.zone_count_max_entry = tk.Entry(self.groupBox9)\n        self.zone_count_max_entry.place(x=100, y=8, width=36)\n        self.zone_count_max_entry.insert(0, "4")\n\n\n        tk.Label(self.groupBox9, text="Yarıçap").place(x=156, y=8)\n        self.zone_radius_min_entry = tk.Entry(self.groupBox9)\n        self.zone_radius_min_entry.place(x=214, y=8, width=46)\n        self.zone_radius_min_entry.insert(0, "60")\n        tk.Label(self.groupBox9, text="-").place(x=264, y=8)\n        self.zone_radius_max_entry = tk.Entry(self.groupBox9)\n        self.zone_radius_max_entry.place(x=276, y=8, width=46)\n        self.zone_radius_max_entry.insert(0, "140")\n\n\n        tk.Label(\n            self.groupBox9,\n            text=f"Hız ×{SLOW_ZONE_FACTOR:g} (sabit)",\n        ).place(x=340, y=8)\n\n\n        self.zones_active_var = tk.BooleanVar(value=False)\n        tk.Checkbutton(\n            self.groupBox9,\n            text="Start\'ta bölgeler aktif",\n            variable=self.zones_active_var,\n            command=self.on_zones_toggled,\n        ).place(x=470, y=6)\n\n\n        self.ZoneGenerateButton = tk.Button(\n            self.groupBox9,\n            text="Yeni Bölgeler",\n            command=self.generate_slow_zones,\n        )\n        self.ZoneGenerateButton.place(x=650, y=2, width=120, height=32)\n\n\n        self.fast_training_var = tk.BooleanVar(value=True)\n        tk.Checkbutton(\n            self.groupBox9,\n            text="Hızlı eğitim",\n            variable=self.fast_training_var,\n        ).place(x=790, y=6)\n\n\n        self.ZoneTrainButton = tk.Button(\n            self.groupBox9,\n            text=ZONE_TRAIN_TEXT,\n            font=("Microsoft Sans Serif", 11),\n            command=self.toggle_zone_training,\n        )\n        self.ZoneTrainButton.place(x=920, y=2, width=420, height=32)\n\n\n    # ------------------------------------------------------------------ #\n    # Algoritma secimi                                                   #\n    # ------------------------------------------------------------------ #\n\n    def select_algorithm(self, algorithm_name: str) -> None:\n        """Registry ile kurar; registry tanimiyorsa yerel sinifi kullanir."""\n        try:\n            self.simulation_engine.set_algorithm(algorithm_name)\n        except Exception:\n            cls = LOCAL_ALGORITHMS.get(algorithm_name)\n            if cls is None:\n                raise\n            self.simulation_engine.algorithm = cls()\n            self.simulation_engine.algorithm.reset()\n        self.sync_algorithm_combo()\n\n\n    def populate_algorithms(self) -> None:\n        metadata = list(self.simulation_engine.get_algorithm_metadata())\n        self.algorithm_name_by_label = {\n            item["display_name"]: item["name"]\n            for item in metadata\n        }\n        known_names = set(self.algorithm_name_by_label.values())\n        for name, cls in LOCAL_ALGORITHMS.items():\n            if name not in known_names:\n                self.algorithm_name_by_label[cls.display_name] = name\n\n\n        self.algorithm_combo["values"] = list(self.algorithm_name_by_label)\n        self.sync_algorithm_combo()\n\n\n    def sync_algorithm_combo(self) -> None:\n        current_name = self.simulation_engine.get_current_algorithm_name()\n        label = next(\n            (\n                lbl\n                for lbl, name in self.algorithm_name_by_label.items()\n                if name == current_name\n            ),\n            None,\n        )\n        if label is None:\n            labels = list(self.algorithm_name_by_label)\n            label = labels[0] if labels else ""\n        if label:\n            self.algorithm_combo.set(label)\n\n\n    def on_algorithm_selected(self, event=None) -> None:\n        label = self.algorithm_combo.get()\n        algorithm_name = self.algorithm_name_by_label.get(label)\n        if algorithm_name:\n            self.stop_active_simulation()\n            try:\n                self.select_algorithm(algorithm_name)\n            except Exception as exc:\n                messagebox.showerror("Algoritma", str(exc))\n\n\n    # ------------------------------------------------------------------ #\n    # Yavaslatma bolgeleri                                               #\n    # ------------------------------------------------------------------ #\n\n    def canvas_size(self):\n        width = self.canvas.winfo_width()\n        height = self.canvas.winfo_height()\n        if width <= 1 or height <= 1:\n            width = int(self.canvas["width"])\n            height = int(self.canvas["height"])\n        return width, height\n\n\n    def build_slow_zone_config(self) -> SlowZoneConfig:\n        width, height = self.canvas_size()\n        config = SlowZoneConfig(\n            enabled=True,\n            count_min=int(self.zone_count_min_entry.get()),\n            count_max=int(self.zone_count_max_entry.get()),\n            radius_min=float(self.zone_radius_min_entry.get()),\n            radius_max=float(self.zone_radius_max_entry.get()),\n            speed_factor=SLOW_ZONE_FACTOR,\n            canvas_width=width,\n            canvas_height=height,\n            regenerate_on_start=False,\n        )\n        config.validate()\n        return config\n\n\n    def generate_slow_zones(self) -> None:\n        try:\n            config = self.build_slow_zone_config()\n        except ValueError as exc:\n            messagebox.showerror("Yavaşlatma Bölgeleri", str(exc))\n            return\n        self.simulation_engine.set_slow_zone_config(config)\n        self.simulation_engine.generate_slow_zones()\n        self.zones_active_var.set(True)\n        self.draw_canvas()\n\n\n    def on_zones_toggled(self) -> None:\n        if self.training_running:\n            return\n        if not self.zones_active_var.get():\n            self.simulation_engine.set_slow_zone_config(None)\n        self.draw_canvas()\n\n\n    def draw_slow_zones(self) -> None:\n        for zone in getattr(self.simulation_engine, "slow_zones", []):\n            self.canvas.create_oval(\n                zone.x - zone.radius,\n                zone.y - zone.radius,\n                zone.x + zone.radius,\n                zone.y + zone.radius,\n                fill="#fdebd3",\n                outline="#e67e22",\n                width=2,\n                dash=(6, 4),\n            )\n\n\n    # ------------------------------------------------------------------ #\n    # Egitim                                                             #\n    # ------------------------------------------------------------------ #\n\n    def toggle_training(self) -> None:\n        self._toggle_training("normal")\n\n\n    def toggle_zone_training(self) -> None:\n        self._toggle_training("zones")\n\n\n    def _toggle_training(self, mode: str) -> None:\n        if self.training_running:\n            self.stop_active_simulation()\n            return\n\n\n        uav_count = len(self.simulation_engine.uavs)\n        goal_count = len(self.simulation_engine.goals)\n\n\n        if uav_count == 0 or goal_count == 0:\n            messagebox.showerror(\n                "Eğitim",\n                "Önce en az bir UAV ve bir hedef oluşturmalısınız.",\n            )\n            return\n\n\n        if any(\n            isinstance(uav, co_Drone)\n            for uav in self.simulation_engine.uavs\n        ):\n            messagebox.showerror(\n                "Eğitim",\n                "Bu eğitim döngüsü yalnızca simülasyon UAV\'leri içindir. "\n                "CoDrone kullanmadan UAV oluşturunuz.",\n            )\n            return\n\n\n        try:\n            self.build_simulation_config()\n            zone_config = self.build_slow_zone_config() if mode == "zones" else None\n            self.stop_active_simulation()\n\n\n            # Normal model bolgesiz, bolgeli model bolgeli ortamda egitilir.\n            self.simulation_engine.set_slow_zone_config(zone_config)\n            # Egitim her zaman taze algoritma ile baslar: kendi "last" kaydini yukler.\n            self.select_algorithm(ZONES_RL_NAME if mode == "zones" else NORMAL_RL_NAME)\n\n\n            self.training_uav_count = uav_count\n            self.training_goal_count = goal_count\n            self.training_mode = mode\n            self.training_running = True\n            self.simulation_engine.algorithm.enable_training(True)\n            if mode == "zones":\n                self.ZoneTrainButton.config(text=STOP_TEXT)\n            else:\n                self.TrainButton.config(text=STOP_TEXT)\n\n\n            self.start_training_episode()\n\n\n        except (ValueError, TypeError, CoDroneDependencyError) as exc:\n            self.stop_active_simulation()\n            messagebox.showerror("Eğitim Hatası", str(exc))\n\n\n    def start_training_episode(self) -> None:\n        if not self.training_running:\n            return\n\n\n        self.simulation_engine.stop_simulation()\n\n\n        width, height = self.canvas_size()\n\n\n        self.simulation_engine.generate_goals(\n            self.training_goal_count,\n            width,\n            height,\n        )\n        self.simulation_engine.generate_uavs(\n            self.training_uav_count,\n            width,\n            height,\n        )\n        if self.training_mode == "zones":\n            self.simulation_engine.generate_slow_zones()\n\n\n        self.simulation_engine.start_simulation()\n        self.draw_canvas()\n\n\n    def build_simulation_config(self) -> SimulationConfig:\n        return SimulationConfig(\n            target_eval_mode=(\n                "single_visit"\n                if self.training_running\n                else self.target_eval_mode.get()\n            ),\n            threshold1=float(self.threshold1_entry.get()),\n            threshold2=float(self.threshold2_entry.get()),\n            simulation_time=float(self.simulation_time_entry.get()),\n            uav_speed=float(self.uav_speed_entry.get()),\n        )\n\n\n    def update_connection_threshold(self, value):\n        try:\n            self.simulation_engine.comm_thr = float(value)\n            self.draw_canvas()\n        except ValueError:\n            messagebox.showerror("Error", "Invalid threshold value!")\n\n\n    def add_goal(self):\n        try:\n            x = int(self.textBox8.get())\n            y = int(self.textBox7.get())\n            self.stop_active_simulation()\n            self.simulation_engine.add_goal(x, y)\n            self.draw_canvas()\n            messagebox.showinfo(\n                "Success",\n                f"Goal {len(self.simulation_engine.goals)} "\n                f"added at ({x}, {y}).",\n            )\n        except ValueError:\n            messagebox.showerror(\n                "Error",\n                "Invalid numeric input for X or Y.",\n            )\n\n\n    def generate_ground(self):\n        try:\n            x = int(self.textBox3.get())\n            y = int(self.textBox4.get())\n            self.stop_active_simulation()\n            self.simulation_engine.generate_ground(x, y)\n            self.draw_canvas()\n            messagebox.showinfo(\n                "Success",\n                f"Ground generated at ({x}, {y}).",\n            )\n        except ValueError:\n            messagebox.showerror(\n                "Error",\n                "Invalid numeric input for X or Y.",\n            )\n\n\n    def generate_goals(self):\n        try:\n            goal_count = int(self.textBox2.get())\n            self.stop_active_simulation()\n            width, height = self.canvas_size()\n            self.simulation_engine.generate_goals(goal_count, width, height)\n            self.draw_canvas()\n            messagebox.showinfo(\n                "Success",\n                f"{goal_count} goals generated successfully!",\n            )\n        except ValueError:\n            messagebox.showerror(\n                "Error",\n                "Invalid input! Please enter a numeric value.",\n            )\n\n\n    def generate_uavs(self):\n        try:\n            uav_count = int(self.textBox1.get())\n            if uav_count <= 0:\n                messagebox.showerror(\n                    "Error",\n                    "UAV number must be a positive integer.",\n                )\n                return\n\n\n            self.stop_active_simulation()\n            self.simulation_engine.uavs = []\n            width, height = self.canvas_size()\n\n\n            if self.use_co_drone_var.get():\n                co_uav = co_Drone(\n                    pos=Vector(50, 50),\n                    uav_no=1,\n                    ground=self.simulation_engine.ground,\n                    command_queue=self.real_drone_commands,\n                )\n                self.simulation_engine.add_existing_uav(co_uav)\n\n\n                remaining_count = uav_count - 1\n                if remaining_count > 0:\n                    normal_uavs = GenerateUAV.run(\n                        remaining_count,\n                        self.simulation_engine.comm_thr,\n                        ground=self.simulation_engine.ground,\n                        canvas_width=width,\n                        canvas_height=height,\n                    )\n                    for uav in normal_uavs:\n                        self.simulation_engine.add_existing_uav(uav)\n            else:\n                self.simulation_engine.generate_uavs(uav_count, width, height)\n\n\n            self.draw_canvas()\n            messagebox.showinfo(\n                "Success",\n                f"{uav_count} UAVs generated successfully!",\n            )\n        except ValueError:\n            messagebox.showerror(\n                "Error",\n                "Invalid input! Please enter a numeric value.",\n            )\n\n\n    def add_uav(self):\n        try:\n            x = int(self.textBox6.get())\n            y = int(self.textBox5.get())\n            self.stop_active_simulation()\n            self.simulation_engine.add_uav(x, y)\n            self.draw_canvas()\n            messagebox.showinfo(\n                "Success",\n                f"UAV {len(self.simulation_engine.uavs)} "\n                f"added at ({x}, {y}).",\n            )\n        except ValueError:\n            messagebox.showerror(\n                "Error",\n                "Invalid numeric input for X or Y.",\n            )\n\n\n    def draw_canvas(self):\n        self.canvas.delete("all")\n\n\n        self.draw_slow_zones()\n\n\n        if self.simulation_engine.ground:\n            self.simulation_engine.ground.draw(self.canvas)\n\n\n        for goal in self.simulation_engine.goals:\n            goal.draw(self.canvas)\n\n\n        for uav in self.simulation_engine.uavs:\n            uav.uav_id = None\n            uav.label_id = None\n            uav.draw(self.canvas)\n\n\n        self.draw_communication_lines()\n\n\n    def reset_simulation(self):\n        self.stop_active_simulation()\n        self.simulation_engine.reset_simulation()\n        self.draw_canvas()\n        messagebox.showinfo(\n            "Reset",\n            "Simulation has been reset.",\n        )\n\n\n    def save_to_file(self):\n        file_path = filedialog.asksaveasfilename(\n            title="Save Simulation Data",\n            defaultextension=".json",\n            filetypes=[\n                ("JSON Files", "*.json"),\n                ("All Files", "*.*"),\n            ],\n        )\n        if not file_path:\n            return\n\n\n        try:\n            data = self.simulation_engine.to_dict()\n            data["CommThreshold"] = self.simulation_engine.comm_thr\n            data["Algorithm"] = (\n                self.simulation_engine.get_current_algorithm_name()\n            )\n\n\n            config = self.build_simulation_config()\n            data["TargetEvalMode"] = config.target_eval_mode\n            data["Threshold1"] = config.threshold1\n            data["Threshold2"] = config.threshold2\n            data["SimulationTime"] = config.simulation_time\n            data["UavSpeed"] = config.uav_speed\n\n\n            with open(file_path, "w", encoding="utf-8") as file:\n                json.dump(data, file, indent=4)\n\n\n            messagebox.showinfo(\n                "Success",\n                f"Simulation data saved to {file_path}.",\n            )\n        except Exception as exc:\n            messagebox.showerror(\n                "Error",\n                f"Failed to save data: {exc}",\n            )\n\n\n    def load_from_file(self):\n        file_path = filedialog.askopenfilename(\n            title="Load Simulation Data",\n            filetypes=[\n                ("JSON Files", "*.json"),\n                ("All Files", "*.*"),\n            ],\n        )\n        if not file_path:\n            return\n\n\n        try:\n            self.stop_active_simulation()\n\n\n            with open(file_path, "r", encoding="utf-8") as file:\n                data = json.load(file)\n\n\n            if "CommThreshold" in data:\n                self.threshold_scale.set(\n                    float(data["CommThreshold"])\n                )\n\n\n            if "TargetEvalMode" in data:\n                self.target_eval_mode.set(\n                    str(data["TargetEvalMode"])\n                )\n\n\n            self.set_entry_value(\n                self.threshold1_entry,\n                data.get("Threshold1"),\n            )\n            self.set_entry_value(\n                self.threshold2_entry,\n                data.get("Threshold2"),\n            )\n            self.set_entry_value(\n                self.simulation_time_entry,\n                data.get("SimulationTime"),\n            )\n            self.set_entry_value(\n                self.uav_speed_entry,\n                data.get("UavSpeed"),\n            )\n\n\n            algorithm_name = data.get("Algorithm")\n            if algorithm_name:\n                self.select_algorithm(algorithm_name)\n                self.populate_algorithms()\n\n\n            self.simulation_engine.load_from_dict(data)\n            self.attach_runtime_uav_dependencies(\n                self.simulation_engine.uavs,\n                self.real_drone_commands,\n            )\n\n\n            self.draw_canvas()\n            messagebox.showinfo(\n                "Success",\n                f"Simulation data loaded from {file_path}.",\n            )\n        except Exception as exc:\n            messagebox.showerror(\n                "Error",\n                f"Failed to load data: {exc}",\n            )\n\n\n    def draw_communication_lines(self):\n        uavs = self.simulation_engine.uavs\n        ground = self.simulation_engine.ground\n        comm_thr = self.simulation_engine.comm_thr\n\n\n        if not uavs:\n            return\n\n\n        adj_matrix = MatrixOperation.adj_matrix(uavs, ground)\n        components = MatrixOperation.find_connected_components(\n            adj_matrix,\n            comm_thr,\n        )\n        risky_links = MatrixOperation.find_risky_links(\n            components,\n            adj_matrix,\n            comm_thr,\n        )\n\n\n        for i, uav1 in enumerate(uavs):\n            for j, uav2 in enumerate(uavs):\n                if i < j and adj_matrix[i, j] <= comm_thr * 0.9:\n                    self.canvas.create_line(\n                        uav1.pos.x,\n                        uav1.pos.y,\n                        uav2.pos.x,\n                        uav2.pos.y,\n                        fill="green",\n                        width=3,\n                    )\n\n\n        if ground:\n            ground_idx = len(uavs)\n            for i, uav in enumerate(uavs):\n                if adj_matrix[i, ground_idx] <= comm_thr * 0.9:\n                    self.canvas.create_line(\n                        uav.pos.x,\n                        uav.pos.y,\n                        ground.pos.x,\n                        ground.pos.y,\n                        fill="green",\n                        width=3,\n                    )\n\n\n        for u, v in risky_links:\n            uav1 = uavs[u] if u < len(uavs) else ground\n            uav2 = uavs[v] if v < len(uavs) else ground\n\n\n            self.canvas.create_line(\n                uav1.pos.x,\n                uav1.pos.y,\n                uav2.pos.x,\n                uav2.pos.y,\n                fill="red",\n                width=3,\n            )\n\n\n    def start_real_drone_session(self) -> None:\n        if not self.simulation_engine.uavs:\n            return\n\n\n        first_uav = self.simulation_engine.uavs[0]\n        if not isinstance(first_uav, co_Drone):\n            return\n\n\n        if first_uav.drone is None:\n            raise CoDroneDependencyError(\n                "codrone_edu is not installed. "\n                "CoDrone mode cannot be started."\n            )\n\n\n        if self.real_drone_thread and self.real_drone_thread.is_alive():\n            return\n\n\n        self.real_drone_thread = RealDroneThread(\n            first_uav,\n            self.real_drone_commands,\n        )\n        self.real_drone_thread.start()\n        self.real_drone_commands.put({"type": "TAKEOFF"})\n\n\n    def stop_real_drone_session(self) -> None:\n        if self.real_drone_thread and self.real_drone_thread.is_alive():\n            try:\n                self.real_drone_thread.handle_command({"type": "LAND"})\n            except Exception:\n                pass\n\n\n            self.real_drone_thread.stop()\n            self.real_drone_thread.join(timeout=2)\n\n\n        self.real_drone_thread = None\n\n\n    def stop_active_simulation(self) -> None:\n        algorithm = self.simulation_engine.algorithm\n        if hasattr(algorithm, "enable_training"):\n            algorithm.enable_training(False)\n        self.training_running = False\n        self.training_mode = None\n        self.TrainButton.config(text=TRAIN_TEXT)\n        self.ZoneTrainButton.config(text=ZONE_TRAIN_TEXT)\n\n\n        self.stop_real_drone_session()\n        self.simulation_engine.stop_simulation()\n        self.StartButton.config(text="Start")\n\n\n    @staticmethod\n    def attach_runtime_uav_dependencies(uavs, command_queue) -> None:\n        for uav in uavs:\n            if isinstance(uav, co_Drone):\n                uav.command_queue = command_queue\n\n\n    @staticmethod\n    def set_entry_value(entry, value) -> None:\n        if value is None:\n            return\n\n\n        previous_state = entry.cget("state")\n\n\n        if previous_state == "disabled":\n            entry.config(state="normal")\n\n\n        entry.delete(0, tk.END)\n        entry.insert(0, str(value))\n\n\n        if previous_state == "disabled":\n            entry.config(state=previous_state)\n\n\n    def start_simulation(self):\n        if self.training_running:\n            self.stop_active_simulation()\n            return\n\n\n        if not self.simulation_engine.simulation_running:\n            try:\n                if self.zones_active_var.get():\n                    self.simulation_engine.set_slow_zone_config(\n                        self.build_slow_zone_config()\n                    )\n                    if not self.simulation_engine.slow_zones:\n                        self.simulation_engine.generate_slow_zones()\n                else:\n                    self.simulation_engine.set_slow_zone_config(None)\n\n\n                self.simulation_engine.start_simulation()\n                self.start_real_drone_session()\n\n\n            except (ValueError, TypeError, CoDroneDependencyError) as exc:\n                messagebox.showerror("Error", str(exc))\n                self.simulation_engine.stop_simulation()\n                return\n\n\n            self.StartButton.config(text="Stop")\n\n\n        else:\n            self.stop_real_drone_session()\n            self.simulation_engine.stop_simulation()\n            self.StartButton.config(text="Start")\n\n\n    def run(self):\n        self.mainloop()\n\n\n    def update_loop(self):\n        if self.simulation_engine.simulation_running:\n            steps = (\n                FAST_TRAINING_STEPS_PER_TICK\n                if self.training_running and self.fast_training_var.get()\n                else 1\n            )\n            stop_reason = None\n            for _ in range(steps):\n                try:\n                    stop_reason = self.simulation_engine.move_uavs()\n                except (ValueError, TypeError, RuntimeError) as exc:\n                    self.stop_active_simulation()\n                    messagebox.showerror("Error", str(exc))\n                    stop_reason = None\n                    break\n                if stop_reason is not None or not self.simulation_engine.simulation_running:\n                    break\n\n\n            if stop_reason in {\n                "all_goals_visited",\n                "network_disconnected",\n                "time_elapsed",\n            }:\n                if self.training_running:\n                    try:\n                        self.start_training_episode()\n\n\n                    except (\n                        ValueError,\n                        TypeError,\n                        CoDroneDependencyError,\n                    ) as exc:\n                        self.stop_active_simulation()\n                        messagebox.showerror(\n                            "Eğitim Hatası",\n                            str(exc),\n                        )\n\n\n                else:\n                    self.stop_active_simulation()\n\n\n                    if stop_reason == "all_goals_visited":\n                        messagebox.showinfo(\n                            "Simulation Complete",\n                            "All goals have been visited.",\n                        )\n                    elif stop_reason == "network_disconnected":\n                        messagebox.showinfo(\n                            "Simulation Complete",\n                            "Network disconnected.",\n                        )\n                    else:\n                        messagebox.showinfo(\n                            "Simulation Complete",\n                            "Simulation time has elapsed.",\n                        )\n\n\n        self.draw_canvas()\n        self.after(100, self.update_loop)\n\n\n\ndef main() -> None:\n    app = MainWindow()\n    app.run()\n\n\n\nif __name__ == "__main__":\n    main()\n',
    'train_headless.py': '"""\nGUI\'siz (headless) egitim.\n\nProje kokunden calistir (ground_main.py ile ayni klasor):\n    python train_headless.py\n    python train_headless.py --minutes 60\n    python train_headless.py --fresh --episodes 30000\n    python train_headless.py --zones --zone-count 2 4 --zone-radius 60 140\n\n--zones ile yavaslatma bolgeli model egitilir (ayri kayit:\n./model/drone_dqn_zones_*.pth). Kendi kaydi yoksa normal modelden baslar.\nBolgeler her bolumde seed\'li ve rastgele uretilir; ajana verilmez.\n\n- Ayni SimulationEngine ve ayni DroneDQNAlgorithm kullanilir, sadece cizim yok.\n- Mufredat: kolay senaryolardan (yakin hedef, siki dizilim) GUI\'deki\n  uretecilere kadar. Asama, son 100 egitim bolumundeki basari orani\n  esigi gecince ilerler. Bunlar kural degil, senaryo ayaridir.\n- Belirli araliklarla seed\'li sabit senaryolarda epsilon=0 degerlendirme.\n  GUI\'deki dagilima (son asama) gore en iyi model\n  ./model/drone_dqn_shared_best.pth olarak kaydedilir. GUI\'de Start\n  (egitim kapali) bu dosyayi yukler.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport math\nimport os\nimport random\nimport time\nfrom collections import deque\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nimport torch\n\nfrom algorithms.model import DroneDQNAlgorithm, DroneDQNSlowZoneAlgorithm\nfrom algorithms.reinforcementagent import MAX_EPISODE_STEPS, SharedAgent\nfrom simulation_core.config import SimulationConfig\nfrom simulation_core.engine import SimulationEngine\nfrom simulation_core.slow_zones import SlowZoneConfig\n\n\nCANVAS_W = 960\nCANVAS_H = 760\nBORDER = 40\nMIN_GOAL_SEP = 50.0\n\nPROMOTE_WINDOW = 100\nPROMOTE_SUCCESS = 0.6\nMIN_STAGE_EPISODES = 200\n\n\n@dataclass(frozen=True)\nclass Stage:\n    name: str\n    uavs: Tuple[int, int]\n    goals: Tuple[int, int]\n    comm_factor: Tuple[float, float]  # drone\'lar arasi yerlesim, x comm_thr\n    goal_dist: Tuple[float, float]    # hedefin drone\'a uzakligi, x comm_thr\n    ground_prob: float\n    use_engine_generators: bool = False\n\n\nSTAGES: Tuple[Stage, ...] = (\n    Stage("s1_kolay", (2, 3), (2, 3), (0.5, 0.6), (0.5, 1.2), 0.0),\n    Stage("s2", (3, 4), (3, 5), (0.6, 0.7), (0.5, 1.8), 0.3),\n    Stage("s3", (3, 5), (5, 8), (0.7, 0.8), (0.5, 2.5), 0.3),\n    Stage("s4", (3, 6), (8, 11), (0.8, 0.9), (0.5, 3.0), 0.3),\n    Stage("gui", (3, 6), (8, 15), (0.9, 0.9), (0.0, 0.0), 0.3, True),\n)\n\n\n# ====================================================================== #\n# Senaryo                                                                #\n# ====================================================================== #\n\ndef _inside(x: float, y: float, w: int, h: int) -> bool:\n    return BORDER <= x <= w - BORDER and BORDER <= y <= h - BORDER\n\n\ndef _far_enough(x: float, y: float, avoid: Sequence[Tuple[float, float]], sep: float) -> bool:\n    return all(math.hypot(x - ax, y - ay) >= sep for ax, ay in avoid)\n\n\ndef _sample_near(\n    rng: random.Random,\n    anchors: Sequence[Tuple[float, float]],\n    rmin: float,\n    rmax: float,\n    w: int,\n    h: int,\n    avoid: Sequence[Tuple[float, float]] = (),\n    sep: float = 0.0,\n) -> Tuple[float, float]:\n    for _ in range(400):\n        ax, ay = rng.choice(anchors)\n        ang = rng.uniform(0.0, 2.0 * math.pi)\n        r = rng.uniform(rmin, rmax)\n        x, y = ax + r * math.cos(ang), ay + r * math.sin(ang)\n        if _inside(x, y, w, h) and _far_enough(x, y, avoid, sep):\n            return x, y\n    for _ in range(400):\n        x = rng.uniform(BORDER, w - BORDER)\n        y = rng.uniform(BORDER, h - BORDER)\n        if _far_enough(x, y, avoid, sep):\n            return x, y\n    return rng.uniform(BORDER, w - BORDER), rng.uniform(BORDER, h - BORDER)\n\n\ndef build_scenario(engine: SimulationEngine, stage: Stage, seed: int, w: int, h: int) -> None:\n    rng = random.Random(seed)\n    env = engine.environment\n    env.reset()\n\n    n_uav = rng.randint(*stage.uavs)\n    n_goal = rng.randint(*stage.goals)\n    use_ground = rng.random() < stage.ground_prob\n    cx = rng.uniform(0.3 * w, 0.7 * w)\n    cy = rng.uniform(0.3 * h, 0.7 * h)\n\n    if use_ground:\n        engine.generate_ground(int(round(cx)), int(round(cy)))\n\n    # Yavaslatma bolgeleri (config yoksa ya da kapaliysa bos kalir).\n    engine.generate_slow_zones(seed=seed + 7_777_777)\n\n    if stage.use_engine_generators:\n        # GUI ile ayni ureteciler (global random kullaniyorlar).\n        random.seed(seed)\n        engine.generate_goals(n_goal, w, h)\n        engine.generate_uavs(n_uav, w, h)\n        return\n\n    thr = env.comm_thr\n    factor = rng.uniform(*stage.comm_factor)\n    nodes: List[Tuple[float, float]] = [(cx, cy)] if use_ground else []\n    uav_pts: List[Tuple[float, float]] = []\n    for _ in range(n_uav):\n        if nodes:\n            p = _sample_near(rng, nodes, 0.3 * thr, factor * thr, w, h)\n        else:\n            p = (cx, cy)\n        engine.add_uav(int(round(p[0])), int(round(p[1])))\n        nodes.append(p)\n        uav_pts.append(p)\n\n    goal_pts: List[Tuple[float, float]] = []\n    for _ in range(n_goal):\n        p = _sample_near(\n            rng,\n            uav_pts,\n            stage.goal_dist[0] * thr,\n            stage.goal_dist[1] * thr,\n            w,\n            h,\n            goal_pts,\n            MIN_GOAL_SEP,\n        )\n        engine.add_goal(int(round(p[0])), int(round(p[1])))\n        goal_pts.append(p)\n\n\n# ====================================================================== #\n# Bolum ve degerlendirme                                                 #\n# ====================================================================== #\n\ndef run_episode(engine: SimulationEngine, alg: DroneDQNAlgorithm, max_steps: int) -> dict:\n    engine.algorithm = alg\n    alg.last_episode = None\n    engine.start_simulation()\n    stop = None\n    for _ in range(max_steps + 50):\n        stop = engine.move_uavs()\n        if stop is not None:\n            break\n    engine.stop_simulation()\n\n    if alg.last_episode is not None:\n        return alg.last_episode\n    goals = engine.environment.goals\n    return {\n        "reward": float("nan"),\n        "visited": sum(1 for g in goals if g.state == "Visited"),\n        "goals": len(goals),\n        "steps": max_steps,\n        "end": stop or "hard_limit",\n        "role_changes": 0,\n        "rounds": 0,\n    }\n\n\ndef summarize(infos: Sequence[dict]) -> Dict[str, float]:\n    if not infos:\n        return {"success": 0.0, "visited": 0.0, "disconnect": 0.0, "reward": 0.0, "steps": 0.0, "score": 0.0}\n    success = float(np.mean([i["end"] == "all_goals_visited" for i in infos]))\n    visited = float(np.mean([i["visited"] / max(i["goals"], 1) for i in infos]))\n    disconnect = float(np.mean([i["end"] == "network_disconnected" for i in infos]))\n    rewards = [i["reward"] for i in infos if not math.isnan(i["reward"])]\n    return {\n        "success": success,\n        "visited": visited,\n        "disconnect": disconnect,\n        "reward": float(np.mean(rewards)) if rewards else float("nan"),\n        "steps": float(np.mean([i["steps"] for i in infos])),\n        "score": success + visited,\n    }\n\n\ndef evaluate(\n    engine: SimulationEngine,\n    alg: DroneDQNAlgorithm,\n    stage: Stage,\n    seeds: Sequence[int],\n    w: int,\n    h: int,\n    max_steps: int,\n) -> Dict[str, float]:\n    infos = []\n    for s in seeds:\n        build_scenario(engine, stage, s, w, h)\n        infos.append(run_episode(engine, alg, max_steps))\n    return summarize(infos)\n\n\ndef _fmt(stats: Dict[str, float]) -> str:\n    return (\n        f"basari {stats[\'success\']:.2f} | ziyaret {stats[\'visited\']:.2f} | "\n        f"kopma {stats[\'disconnect\']:.2f} | odul {stats[\'reward\']:.2f} | "\n        f"adim {stats[\'steps\']:.0f}"\n    )\n\n\n# ====================================================================== #\n# Ana dongu                                                              #\n# ====================================================================== #\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description="Drone DQN headless egitim")\n    parser.add_argument("--episodes", type=int, default=20_000)\n    parser.add_argument("--minutes", type=float, default=0.0, help="0 = sure siniri yok")\n    parser.add_argument("--seed", type=int, default=0)\n    parser.add_argument("--max-steps", type=int, default=MAX_EPISODE_STEPS)\n    parser.add_argument("--log-every", type=int, default=50)\n    parser.add_argument("--eval-every", type=int, default=250)\n    parser.add_argument("--eval-episodes", type=int, default=30)\n    parser.add_argument("--start-stage", type=int, default=0)\n    parser.add_argument("--comm-thr", type=float, default=200.0)\n    parser.add_argument("--speed", type=float, default=5.0)\n    parser.add_argument("--width", type=int, default=CANVAS_W)\n    parser.add_argument("--height", type=int, default=CANVAS_H)\n    parser.add_argument("--threads", type=int, default=1)\n    parser.add_argument("--fresh", action="store_true", help="kayitli modeli yukleme, sifirdan basla")\n    parser.add_argument("--zones", action="store_true", help="yavaslatma bolgeli modeli egit")\n    parser.add_argument("--zone-count", type=int, nargs=2, default=(2, 4), metavar=("MIN", "MAX"))\n    parser.add_argument("--zone-radius", type=float, nargs=2, default=(60.0, 140.0), metavar=("MIN", "MAX"))\n    parser.add_argument("--zone-factor", type=float, default=0.5, help="bolge icinde hiz carpani")\n    args = parser.parse_args()\n\n    torch.set_num_threads(max(1, args.threads))\n    random.seed(args.seed)\n    np.random.seed(args.seed)\n\n    engine = SimulationEngine(comm_thr=args.comm_thr)\n    engine.set_config_provider(\n        lambda: SimulationConfig(target_eval_mode="single_visit", uav_speed=args.speed)\n    )\n\n    alg_cls = DroneDQNSlowZoneAlgorithm if args.zones else DroneDQNAlgorithm\n    checkpoint_last = alg_cls.checkpoint_last\n    checkpoint_best = alg_cls.checkpoint_best\n\n    if args.zones:\n        engine.set_slow_zone_config(\n            SlowZoneConfig(\n                enabled=True,\n                count_min=args.zone_count[0],\n                count_max=args.zone_count[1],\n                radius_min=args.zone_radius[0],\n                radius_max=args.zone_radius[1],\n                speed_factor=args.zone_factor,\n                canvas_width=args.width,\n                canvas_height=args.height,\n                regenerate_on_start=False,\n            )\n        )\n        print(\n            f"Yavaslatma bolgeleri: {args.zone_count[0]}-{args.zone_count[1]} adet, "\n            f"yaricap {args.zone_radius[0]:.0f}-{args.zone_radius[1]:.0f}, carpan {args.zone_factor}"\n        )\n\n    agent = SharedAgent(seed=args.seed)\n    if not args.fresh:\n        loaded = alg_cls.load_into(agent, training=True)\n        if loaded is not None:\n            print(f"Yuklendi: {loaded} (karar {agent.decisions}, guncelleme {agent.updates})")\n        else:\n            print("Kayit yok, sifirdan basliyor.")\n    else:\n        agent.best_avg = float("-inf")\n\n    train_alg = alg_cls(\n        max_episode_steps=args.max_steps, seed=args.seed, verbose=False, auto_save=False\n    )\n    train_alg.enable_training(True)\n    train_alg.agent = agent\n\n    eval_alg = alg_cls(\n        max_episode_steps=args.max_steps, seed=args.seed, verbose=False, auto_save=False\n    )\n    eval_alg.enable_training(False)\n    eval_alg.agent = agent\n\n    stage_idx = max(0, min(args.start_stage, len(STAGES) - 1))\n    stage_hist: deque = deque(maxlen=PROMOTE_WINDOW)\n    stage_episodes = 0\n    recent: deque = deque(maxlen=args.log_every)\n    eval_seeds = [10_000_000 + k for k in range(args.eval_episodes)]\n    seed_base = args.seed * 1_000_003\n\n    print(f"Model: {alg_cls.display_name} | Asama: {STAGES[stage_idx].name}")\n    t0 = time.time()\n    t_log = t0\n    ep = 0\n    try:\n        while ep < args.episodes:\n            if args.minutes > 0 and time.time() - t0 >= args.minutes * 60:\n                print("Sure doldu.")\n                break\n\n            stage = STAGES[stage_idx]\n            build_scenario(engine, stage, seed_base + ep, args.width, args.height)\n            info = run_episode(engine, train_alg, args.max_steps)\n            ep += 1\n            stage_episodes += 1\n            stage_hist.append(info["end"] == "all_goals_visited")\n            recent.append(info)\n\n            if ep % args.log_every == 0:\n                now = time.time()\n                rate = args.log_every / max(now - t_log, 1e-9)\n                t_log = now\n                loss = f"{agent.last_loss:.4f}" if agent.last_loss is not None else "n/a"\n                print(\n                    f"[ep {ep}] {stage.name} | {_fmt(summarize(list(recent)))} | "\n                    f"eps {agent.epsilon:.3f} | guncelleme {agent.updates} | "\n                    f"loss {loss} | replay {len(agent.memory)} | {rate:.1f} bolum/sn"\n                )\n\n            if (\n                stage_idx < len(STAGES) - 1\n                and stage_episodes >= MIN_STAGE_EPISODES\n                and len(stage_hist) == PROMOTE_WINDOW\n                and float(np.mean(stage_hist)) >= PROMOTE_SUCCESS\n            ):\n                stage_idx += 1\n                stage_episodes = 0\n                stage_hist.clear()\n                print(f"==> Asama ilerledi: {STAGES[stage_idx].name}")\n\n            if ep % args.eval_every == 0:\n                cur = evaluate(engine, eval_alg, STAGES[stage_idx], eval_seeds,\n                               args.width, args.height, args.max_steps)\n                gui = evaluate(engine, eval_alg, STAGES[-1], eval_seeds,\n                               args.width, args.height, args.max_steps)\n                print(f"   DEGERLENDIRME {STAGES[stage_idx].name}: {_fmt(cur)}")\n                print(f"   DEGERLENDIRME gui: {_fmt(gui)}")\n                if gui["score"] > agent.best_avg:\n                    # Headless\'ta best_avg, gui degerlendirme skorunu tutar.\n                    agent.best_avg = gui["score"]\n                    agent.save(checkpoint_best)\n                    print(f"   En iyi model kaydedildi (skor {gui[\'score\']:.3f}).")\n                agent.save(checkpoint_last)\n    except KeyboardInterrupt:\n        print("\\nDurduruldu.")\n    finally:\n        agent.save(checkpoint_last)\n        if not os.path.exists(checkpoint_best):\n            agent.save(checkpoint_best)\n        print(f"Kaydedildi: {checkpoint_last}. Toplam {ep} bolum, {time.time() - t0:.0f} sn.")\n\n\nif __name__ == "__main__":\n    main()\n'
}

